/* Character sheets */
.sheet-intro{display:flex;flex-direction:column;gap:4px;padding:12px 14px;margin-bottom:16px;border:1px solid #55482f;border-radius:7px;background:linear-gradient(110deg,#352d1d,#211f19);color:var(--muted);font-size:12px}.sheet-intro b{font:600 14px var(--serif);color:var(--gold2)}.form-grid>.field.full{margin-top:7px}.ability-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px}.ability-field{display:flex;min-width:0;flex-direction:column;gap:7px;padding:10px 8px;border:1px solid #4b4230;border-radius:6px;background:#1a1915;text-align:center}.ability-field span{font-size:9px;font-weight:700;letter-spacing:.07em;color:#c7b98f;text-transform:uppercase}.ability-field input{text-align:center;font:600 20px var(--serif);padding:8px 4px}.field-hint{display:block;color:var(--muted);font-size:11px;margin-top:8px}.sheet-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.sheet-check-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.sheet-check-grid>label{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 10px;border:1px solid #39352c;border-radius:5px;background:#1a1916;color:#c9c0ad;font-size:11px}.sheet-check-grid select,.sheet-check-grid input{width:auto;max-width:130px;padding:7px;font-size:11px}.form-grid textarea[name^="sheet_"]{width:100%;margin-top:9px;min-height:76px}.modal-wide{width:min(900px,calc(100vw - 32px))}.modal-wide .modal-body{max-height:min(76vh,820px);overflow:auto}.modal-wide .form-grid{align-items:start}
@media(max-width:760px){.modal-wide{width:calc(100vw - 18px);max-height:calc(100dvh - 18px)}.modal-wide .modal-body{max-height:calc(100dvh - 145px);padding:14px}.ability-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.ability-field{padding:9px 5px}.ability-field input{font-size:18px}.sheet-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.sheet-check-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sheet-check-grid>label{padding:8px;font-size:10px}.sheet-check-grid select,.sheet-check-grid input{max-width:105px}}
@media(max-width:380px){.ability-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sheet-check-grid{grid-template-columns:1fr}.sheet-stat-grid{grid-template-columns:1fr}}

