47: -- A profile can only be read/created by its owner. Role changes are intentionally
48: -- excluded from UPDATE so changing roles requires a new account / trusted admin.
49: drop policy if exists seed_profiles_read_self on public.seed_profiles;
50: create policy seed_profiles_read_self on public.seed_profiles
51:   for select to authenticated using (user_id = (select auth.uid()));
52: drop policy if exists seed_profiles_insert_self on public.seed_profiles;
53: create policy seed_profiles_insert_self on public.seed_profiles
54:   for insert to authenticated with check (user_id = (select auth.uid()));
55: drop policy if exists seed_profiles_update_name on public.seed_profiles;
56: create policy seed_profiles_update_name on public.seed_profiles
57:   for update to authenticated using (user_id = (select auth.uid()))
58:   with check (user_id = (select auth.uid()));
59: revoke update on public.seed_profiles from authenticated;
60: grant update (display_name) on public.seed_profiles to authenticated;
