115: create or replace function public.seed_create_profile(p_display_name text, p_app_role text)
116: returns public.seed_profiles
117: language plpgsql security definer set search_path = ''
118: as $$
119: declare result public.seed_profiles;
120: begin
121:   if auth.uid() is null or p_app_role not in ('master', 'player') then
122:     raise exception 'Perfil inválido';
123:   end if;
124:   insert into public.seed_profiles(user_id, display_name, app_role)
125:   values (auth.uid(), left(trim(coalesce(p_display_name, '')), 80), p_app_role)
126:   on conflict (user_id) do nothing;
127:   select * into result from public.seed_profiles where user_id = auth.uid();
128:   return result;
129: end;
130: $$;
