47: -- A profile can only be read/created by its owner. Role changes are intentionally
48: -- excluded from UPDATE so changing roles requires a new account / trusted admin.
49: drop policy if exists seed_profiles_read_self on public.seed_profiles;
50: create policy seed_profiles_read_self on public.seed_profiles
51:   for select to authenticated using (user_id = (select auth.uid()));
52: drop policy if exists seed_profiles_insert_self on public.seed_profiles;
53: create policy seed_profiles_insert_self on public.seed_profiles
54:   for insert to authenticated with check (user_id = (select auth.uid()));
55: drop policy if exists seed_profiles_update_name on public.seed_profiles;
56: create policy seed_profiles_update_name on public.seed_profiles
57:   for update to authenticated using (user_id = (select auth.uid()))
58:   with check (user_id = (select auth.uid()));
59: revoke update on public.seed_profiles from authenticated;
60: grant update (display_name) on public.seed_profiles to authenticated;
61: 
62: -- Campaign payload is visible to the owner and approved members. Approved players
63: -- may update shared play state; only the owner may create or delete a campaign.
64: drop policy if exists seed_campaigns_read_members on public.seed_campaigns;
65: create policy seed_campaigns_read_members on public.seed_campaigns
66:   for select to authenticated using (
67:     owner_id = (select auth.uid()) or exists (
68:       select 1 from public.seed_campaign_members m
69:       where m.campaign_id = id and m.user_id = (select auth.uid())
70:         and m.status = 'active'
71:     )
72:   );
73: drop policy if exists seed_campaigns_insert_owner on public.seed_campaigns;
74: create policy seed_campaigns_insert_owner on public.seed_campaigns
75:   for insert to authenticated with check (
76:     owner_id = (select auth.uid()) and exists (
77:       select 1 from public.seed_profiles p
78:       where p.user_id = (select auth.uid()) and p.app_role = 'master'
79:     )
80:   );
81: drop policy if exists seed_campaigns_update_members on public.seed_campaigns;
82: create policy seed_campaigns_update_members on public.seed_campaigns
83:   for update to authenticated using (
84:     owner_id = (select auth.uid()) or exists (
85:       select 1 from public.seed_campaign_members m
86:       where m.campaign_id = id and m.user_id = (select auth.uid())
87:         and m.status = 'active'
88:     )
89:   ) with check (
90:     owner_id = (select auth.uid()) or exists (
91:       select 1 from public.seed_campaign_members m
92:       where m.campaign_id = id and m.user_id = (select auth.uid())
93:         and m.status = 'active'
94:     )
95:   );
96: drop policy if exists seed_campaigns_delete_owner on public.seed_campaigns;
97: create policy seed_campaigns_delete_owner on public.seed_campaigns
