115: create or replace function public.seed_create_profile(p_display_name text, p_app_role text)
116: returns public.seed_profiles
117: language plpgsql security definer set search_path = ''
118: as $$
119: declare result public.seed_profiles;
120: begin
121:   if auth.uid() is null or p_app_role not in ('master', 'player') then
122:     raise exception 'Perfil inválido';
123:   end if;
124:   insert into public.seed_profiles(user_id, display_name, app_role)
125:   values (auth.uid(), left(trim(coalesce(p_display_name, '')), 80), p_app_role)
126:   on conflict (user_id) do nothing;
127:   select * into result from public.seed_profiles where user_id = auth.uid();
128:   return result;
129: end;
130: $$;
131: 
132: create or replace function public.seed_create_invite(p_campaign_id text)
133: returns text
134: language plpgsql security definer set search_path = ''
135: as $$
136: declare token text;
137: begin
138:   if not exists (select 1 from public.seed_campaigns c
139:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
140:     raise exception 'Somente o Mestre da campanha pode convidar';
141:   end if;
142:   token := encode(extensions.gen_random_bytes(24), 'hex');
143:   insert into public.seed_campaign_invites(campaign_id, token_hash)
144:   values (p_campaign_id, encode(extensions.digest(token, 'sha256'), 'hex'));
145:   return token;
146: end;
147: $$;
148: 
149: create or replace function public.seed_request_join(p_invite_token text)
150: returns text
151: language plpgsql security definer set search_path = ''
152: as $$
153: declare target_campaign text;
154: begin
155:   if auth.uid() is null or coalesce(length(p_invite_token), 0) < 32 then
156:     raise exception 'Convite inválido ou expirado';
157:   end if;
158:   select i.campaign_id into target_campaign
159:   from public.seed_campaign_invites i
160:   where i.token_hash = encode(extensions.digest(p_invite_token, 'sha256'), 'hex')
161:     and i.expires_at > now();
162:   if target_campaign is null then raise exception 'Convite inválido ou expirado'; end if;
163:   insert into public.seed_campaign_members(campaign_id, user_id, member_role, status)
164:   values (target_campaign, auth.uid(), 'player', 'pending')
165:   on conflict (campaign_id, user_id) do nothing;
166:   return target_campaign;
167: end;
168: $$;
169: 
170: create or replace function public.seed_approve_member(p_campaign_id text, p_user_id uuid)
171: returns void
172: language plpgsql security definer set search_path = ''
173: as $$
174: begin
175:   if not exists (select 1 from public.seed_campaigns c
176:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
177:     raise exception 'Somente o Mestre da campanha pode aprovar participantes';
178:   end if;
179:   update public.seed_campaign_members set status = 'active'
180:   where campaign_id = p_campaign_id and user_id = p_user_id and status = 'pending';
181:   if not found then raise exception 'Solicitação não encontrada'; end if;
182: end;
183: $$;
184: 
185: create or replace function public.seed_remove_member(p_campaign_id text, p_user_id uuid)
186: returns void
187: language plpgsql security definer set search_path = ''
188: as $$
189: begin
190:   if not exists (select 1 from public.seed_campaigns c
191:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
192:     raise exception 'Somente o Mestre da campanha pode remover participantes';
193:   end if;
194:   delete from public.seed_campaign_members
195:   where campaign_id = p_campaign_id and user_id = p_user_id;
196: end;
197: $$;
