132: create or replace function public.seed_create_invite(p_campaign_id text)
133: returns text
134: language plpgsql security definer set search_path = ''
135: as $$
136: declare token text;
137: begin
138:   if not exists (select 1 from public.seed_campaigns c
139:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
140:     raise exception 'Somente o Mestre da campanha pode convidar';
141:   end if;
142:   token := encode(extensions.gen_random_bytes(24), 'hex');
143:   insert into public.seed_campaign_invites(campaign_id, token_hash)
144:   values (p_campaign_id, encode(extensions.digest(token, 'sha256'), 'hex'));
