1: -- SEED shared campaigns: run this once in Supabase SQL Editor.
2: -- Uses the Supabase Auth UID as the sole source of identity.
3: create extension if not exists pgcrypto with schema extensions;
4: 
5: create table if not exists public.seed_profiles (
6:   user_id uuid primary key references auth.users(id) on delete cascade,
7:   display_name text not null default '',
8:   app_role text not null check (app_role in ('master', 'player')),
9:   created_at timestamptz not null default now()
10: );
11: 
12: create table if not exists public.seed_campaigns (
13:   id text primary key,
14:   owner_id uuid not null references auth.users(id) on delete cascade,
15:   payload jsonb not null default '{}'::jsonb,
16:   created_at timestamptz not null default now(),
17:   updated_at timestamptz not null default now()
18: );
19: 
20: create table if not exists public.seed_campaign_members (
21:   campaign_id text not null references public.seed_campaigns(id) on delete cascade,
22:   user_id uuid not null references auth.users(id) on delete cascade,
23:   member_role text not null default 'player' check (member_role = 'player'),
24:   status text not null default 'pending' check (status in ('pending', 'active')),
25:   joined_at timestamptz not null default now(),
26:   primary key (campaign_id, user_id)
27: );
28: 
29: create table if not exists public.seed_campaign_invites (
30:   id uuid primary key default gen_random_uuid(),
31:   campaign_id text not null references public.seed_campaigns(id) on delete cascade,
32:   token_hash text not null unique,
33:   expires_at timestamptz not null default (now() + interval '7 days'),
34:   created_at timestamptz not null default now()
35: );
36: 
37: create index if not exists seed_campaign_members_user_idx
38:   on public.seed_campaign_members(user_id, status);
39: create index if not exists seed_campaign_invites_campaign_idx
40:   on public.seed_campaign_invites(campaign_id);
41: 
42: -- Security-definer predicates avoid recursive RLS checks between campaigns and memberships.
43: create or replace function public.seed_is_campaign_owner(p_campaign_id text)
44: returns boolean language sql stable security definer set search_path = ''
45: as $$ select exists (select 1 from public.seed_campaigns c where c.id = p_campaign_id and c.owner_id = auth.uid()) $$;
46: create or replace function public.seed_is_active_member(p_campaign_id text)
47: returns boolean language sql stable security definer set search_path = ''
48: as $$ select exists (select 1 from public.seed_campaign_members m where m.campaign_id = p_campaign_id and m.user_id = auth.uid() and m.status = 'active') $$;
49: revoke all on function public.seed_is_campaign_owner(text) from public, anon;
50: revoke all on function public.seed_is_active_member(text) from public, anon;
51: grant execute on function public.seed_is_campaign_owner(text) to authenticated;
52: grant execute on function public.seed_is_active_member(text) to authenticated;
53: 
54: alter table public.seed_profiles enable row level security;
55: alter table public.seed_campaigns enable row level security;
56: alter table public.seed_campaign_members enable row level security;
57: alter table public.seed_campaign_invites enable row level security;
58: 
59: -- A profile can only be read/created by its owner. Role changes are intentionally
60: -- excluded from UPDATE so changing roles requires a new account / trusted admin.
61: drop policy if exists seed_profiles_read_self on public.seed_profiles;
62: create policy seed_profiles_read_self on public.seed_profiles
63:   for select to authenticated using (user_id = (select auth.uid()));
64: drop policy if exists seed_profiles_insert_self on public.seed_profiles;
65: create policy seed_profiles_insert_self on public.seed_profiles
66:   for insert to authenticated with check (user_id = (select auth.uid()));
67: drop policy if exists seed_profiles_update_name on public.seed_profiles;
68: create policy seed_profiles_update_name on public.seed_profiles
69:   for update to authenticated using (user_id = (select auth.uid()))
70:   with check (user_id = (select auth.uid()));
71: revoke update on public.seed_profiles from authenticated;
72: grant update (display_name) on public.seed_profiles to authenticated;
73: 
74: -- Campaign payload is visible to the owner and approved members. Approved players
75: -- may update shared play state; only the owner may create or delete a campaign.
76: drop policy if exists seed_campaigns_read_members on public.seed_campaigns;
77: create policy seed_campaigns_read_members on public.seed_campaigns
78:   for select to authenticated using (
79:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
80:   );
81: drop policy if exists seed_campaigns_insert_owner on public.seed_campaigns;
82: create policy seed_campaigns_insert_owner on public.seed_campaigns
83:   for insert to authenticated with check (
84:     owner_id = (select auth.uid()) and exists (
85:       select 1 from public.seed_profiles p
86:       where p.user_id = (select auth.uid()) and p.app_role = 'master'
87:     )
88:   );
89: drop policy if exists seed_campaigns_update_members on public.seed_campaigns;
90: create policy seed_campaigns_update_members on public.seed_campaigns
91:   for update to authenticated using (
92:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
93:   ) with check (
94:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
95:   );
96: drop policy if exists seed_campaigns_delete_owner on public.seed_campaigns;
97: create policy seed_campaigns_delete_owner on public.seed_campaigns
98:   for delete to authenticated using (owner_id = (select auth.uid()));
99: 
100: -- Memberships are private: a participant sees their own status; the campaign
101: -- owner sees all requests. Mutations are only available through the RPCs below.
102: drop policy if exists seed_members_read_related on public.seed_campaign_members;
103: create policy seed_members_read_related on public.seed_campaign_members
104:   for select to authenticated using (
105:     user_id = (select auth.uid()) or public.seed_is_campaign_owner(campaign_id)
106:   );
107: revoke insert, update, delete on public.seed_campaign_members from authenticated;
108: 
109: -- Invite hashes are never readable through the client API.
110: revoke all on public.seed_campaign_invites from anon, authenticated;
