112: create or replace function public.seed_create_profile(p_display_name text, p_app_role text)
113: returns public.seed_profiles
114: language plpgsql security definer set search_path = ''
115: as $$
116: declare result public.seed_profiles;
117: begin
118:   if auth.uid() is null or p_app_role not in ('master', 'player') then
119:     raise exception 'Perfil inválido';
120:   end if;
121:   insert into public.seed_profiles(user_id, display_name, app_role)
122:   values (auth.uid(), left(trim(coalesce(p_display_name, '')), 80), p_app_role)
123:   on conflict (user_id) do nothing;
124:   select * into result from public.seed_profiles where user_id = auth.uid();
125:   return result;
126: end;
127: $$;
128: 
129: create or replace function public.seed_create_invite(p_campaign_id text)
130: returns text
131: language plpgsql security definer set search_path = ''
132: as $$
133: declare token text;
134: begin
135:   if not exists (select 1 from public.seed_campaigns c
136:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
137:     raise exception 'Somente o Mestre da campanha pode convidar';
138:   end if;
139:   token := encode(extensions.gen_random_bytes(24), 'hex');
140:   insert into public.seed_campaign_invites(campaign_id, token_hash)
141:   values (p_campaign_id, encode(extensions.digest(token, 'sha256'), 'hex'));
142:   return token;
143: end;
144: $$;
145: 
146: create or replace function public.seed_request_join(p_invite_token text)
147: returns text
148: language plpgsql security definer set search_path = ''
149: as $$
150: declare target_campaign text;
151: begin
152:   if auth.uid() is null or coalesce(length(p_invite_token), 0) < 32 then
153:     raise exception 'Convite inválido ou expirado';
154:   end if;
155:   select i.campaign_id into target_campaign
156:   from public.seed_campaign_invites i
157:   where i.token_hash = encode(extensions.digest(p_invite_token, 'sha256'), 'hex')
158:     and i.expires_at > now();
159:   if target_campaign is null then raise exception 'Convite inválido ou expirado'; end if;
160:   insert into public.seed_campaign_members(campaign_id, user_id, member_role, status)
161:   values (target_campaign, auth.uid(), 'player', 'pending')
162:   on conflict (campaign_id, user_id) do nothing;
163:   return target_campaign;
164: end;
165: $$;
166: 
167: create or replace function public.seed_approve_member(p_campaign_id text, p_user_id uuid)
168: returns void
169: language plpgsql security definer set search_path = ''
170: as $$
171: begin
172:   if not exists (select 1 from public.seed_campaigns c
173:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
174:     raise exception 'Somente o Mestre da campanha pode aprovar participantes';
175:   end if;
176:   update public.seed_campaign_members set status = 'active'
177:   where campaign_id = p_campaign_id and user_id = p_user_id and status = 'pending';
178:   if not found then raise exception 'Solicitação não encontrada'; end if;
179: end;
180: $$;
181: 
182: create or replace function public.seed_remove_member(p_campaign_id text, p_user_id uuid)
183: returns void
184: language plpgsql security definer set search_path = ''
185: as $$
186: begin
187:   if not exists (select 1 from public.seed_campaigns c
188:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
189:     raise exception 'Somente o Mestre da campanha pode remover participantes';
190:   end if;
191:   delete from public.seed_campaign_members
192:   where campaign_id = p_campaign_id and user_id = p_user_id;
193: end;
194: $$;
