  function parseRoll(expression){const m=String(expression).trim().toLowerCase().match(/^(\d*)d(\d+)(?:\s*([+-])\s*(\d+))?$/);if(!m)throw new Error('Use uma fórmula como d20, 2d6+3 ou 1d100.');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[4]||0)*(m[3]==='-'?-1:1);if(count<1||count>100||sides<2||sides>10000||mod>100000||mod< -100000)throw new Error('Limites: até 100 dados, d2–d10000 e modificador de 100000.');const dice=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return{expression:String(expression).trim(),dice,mod,total:dice.reduce((a,b)=>a+b,0)+mod};}
  function recordRoll(expression,author='Mestre'){try{const r=parseRoll(expression);r.id=uid();r.time=Date.now();r.author=author;state.rolls.unshift(r);state.rolls=state.rolls.slice(0,100);const c=currentCampaign();if(c){c.chat=c.chat||[];c.chat.push({id:uid(),author,text:`rolou ${r.expression}: ${r.total}`,roll:true,time:r.time});c.chat=c.chat.slice(-100);}save();if(currentView==='tabletop')renderTabletop();else renderDashboard();return r;}catch(e){toast(e.message);return null;}}
  function diceModal(){const recent=state.rolls.slice(0,8);openModal('Rolar dados',`<form id="roll-form"><div class="field"><label>FÓRMULA</label><input name="formula" value="d20" placeholder="d20, 2d6+3" required></div></form><div class="roll-history">${recent.map(r=>`<div class="roll-item"><span>${escapeHtml(r.expression)} · ${new Date(r.time).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span><b>${r.total}</b></div>`).join('')||'<p class="muted">Suas rolagens aparecerão aqui.</p>'}</div>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-roll-modal>Rolar</button>`);}
  function renderTabletop(){const root=$('#view-root'),c=currentCampaign();if(!c){root.innerHTML=`<div class="empty-state"><b>A mesa precisa de uma campanha</b>Crie ou selecione uma campanha para abrir o mapa, tokens e combate.<br><button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button></div>`;return;}const t=tabletopFor(c),asset=state.assets.find(a=>a.id===t.mapAssetId);root.innerHTML=`<section class="tabletop-view"><div class="session-bar"><div class="session-title">${escapeHtml(c.name)} <small>· ${escapeHtml(getSystem(c.systemId).name)}</small></div><div class="session-tools"><button data-action="new-session" class="hide-mobile">◷ Sessão</button><button data-action="map-image" class="hide-mobile">▧ Mapa</button><button data-action="toggle-grid">Grade: ${t.gridType==='none'?'off':t.grid+'px'}</button><button data-action="add-token">＋ Token</button></div></div><div class="tabletop-layout"><div class="map-tools"><button class="map-tool ${activeTool==='select'?'active':''}" data-tool="select" title="Selecionar / mover">↖</button><button class="map-tool ${activeTool==='pan'?'active':''}" data-tool="pan" title="Mover mapa">✥</button><button class="map-tool ${activeTool==='token'?'active':''}" data-tool="token" title="Adicionar token">♙</button><button class="map-tool ${activeTool==='measure'?'active':''}" data-tool="measure" title="Medir distância">↔</button><button class="map-tool ${activeTool==='fog'?'active':''}" data-tool="fog" title="Ocultar área (pinte no mapa)">▧</button><button class="map-tool ${activeTool==='reveal'?'active':''}" data-tool="reveal" title="Revelar área">☼</button><div class="tool-divider"></div><button class="map-tool" data-action="map-image" title="Escolher mapa">▧</button><button class="map-tool" data-action="toggle-grid" title="Alternar grade">▦</button><button class="map-tool" data-action="center-map" title="Centralizar">⌖</button></div><div class="map-workspace"><canvas id="map-canvas" class="map-canvas" aria-labe