5: create table if not exists public.seed_profiles (
6:   user_id uuid primary key references auth.users(id) on delete cascade,
7:   display_name text not null default '',
8:   app_role text not null check (app_role in ('master', 'player')),
9:   created_at timestamptz not null default now()
10: );
11: 
12: create table if not exists public.seed_campaigns (
13:   id text primary key,
14:   owner_id uuid not null references auth.users(id) on delete cascade,
15:   payload jsonb not null default '{}'::jsonb,
16:   created_at timestamptz not null default now(),
17:   updated_at timestamptz not null default now()
18: );
19: 
20: create table if not exists public.seed_campaign_members (
21:   campaign_id text not null references public.seed_campaigns(id) on delete cascade,
22:   user_id uuid not null references auth.users(id) on delete cascade,
23:   member_role text not null default 'player' check (member_role = 'player'),
24:   status text not null default 'pending' check (status in ('pending', 'active')),
25:   joined_at timestamptz not null default now(),
26:   primary key (campaign_id, user_id)
27: );
