42: -- Security-definer predicates avoid recursive RLS checks between campaigns and memberships.
43: create or replace function public.seed_is_campaign_owner(p_campaign_id text)
44: returns boolean language sql stable security definer set search_path = ''
45: as $$ select exists (select 1 from public.seed_campaigns c where c.id = p_campaign_id and c.owner_id = auth.uid()) $$;
46: create or replace function public.seed_is_active_member(p_campaign_id text)
47: returns boolean language sql stable security definer set search_path = ''
48: as $$ select exists (select 1 from public.seed_campaign_members m where m.campaign_id = p_campaign_id and m.user_id = auth.uid() and m.status = 'active') $$;
49: revoke all on function public.seed_is_campaign_owner(text) from public, anon;
50: revoke all on function public.seed_is_active_member(text) from public, anon;
51: grant execute on function public.seed_is_campaign_owner(text) to authenticated;
52: grant execute on function public.seed_is_active_member(text) to authenticated;
