59: -- A profile can only be read/created by its owner. Role changes are intentionally
60: -- excluded from UPDATE so changing roles requires a new account / trusted admin.
61: drop policy if exists seed_profiles_read_self on public.seed_profiles;
62: create policy seed_profiles_read_self on public.seed_profiles
63:   for select to authenticated using (user_id = (select auth.uid()));
64: drop policy if exists seed_profiles_insert_self on public.seed_profiles;
65: create policy seed_profiles_insert_self on public.seed_profiles
66:   for insert to authenticated with check (user_id = (select auth.uid()));
