      {id:'dnd5e',name:'D&D 5ª Edição',version:'5e',description:'Ficha de fantasia d20 com atributos, perícias, combate, equipamentos e conjuração.',attributes:['Força','Destreza','Constituição','Inteligência','Sabedoria','Carisma'],skills:['Acrobacia','Adestrar Animais','Arcanismo','Atletismo','Atuação','Enganação','Furtividade','História','Intimidação','Intuição','Investigação','Lidar com Animais','Medicina','Natureza','Percepção','Persuasão','Prestidigitação','Religião','Sobrevivência'],dice:'d20',builtin:true,sheetType:'dnd5e'}, 
