  function renderSystems(){const root=$('#view-root');root.innerHTML=`${pageHead('Sistemas de RPG','Regras flexíveis. Sua mesa, suas escolhas.','<button class="primary-btn" data-action="create-system">＋ Novo sistema</button>')}<div class="system-grid">${state.systems.map((s,i)=>`<article class="system-card"><div class="system-symbol">${i===0?'ᚱ':i===1?'⚔':'✧'}</div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.description)}</p><div class="rule-pills">${(s.attributes||[]).slice(0,4).map(a=>`<span>${escapeHtml(a)}</span>`).join('')}<span>${escapeHtml(s.dice||'d20')}</span></div><div class="system-foot"><span class="tag">${s.builtin?'BASE SEED':'PERSONALIZADO'} · v${escapeHtml(s.version||'1.0')}</span><button data-edit-system="${s.id}">Configurar →</button></div></article>`).join('')}</div><div class="settings-panel" style="margin-top:20px"><h3>Um motor de regras sem amarras</h3><p>Os sistemas definem atributos e dados para as fichas. A mesa não impõe classes, níveis ou cálculos: regras específicas podem ser anotadas livremente e as rolagens aceitam qualquer fórmula de dados.</p></div>`;}
  function renderLibrary(){const root=$('#view-root');root.innerHTML=`${pageHead('Biblioteca','Mapas e imagens importados ficam disponíveis neste dispositivo.','<button class="primary-btn" data-action="upload-asset">＋ Importar arquivo</button>')}<div class="toolbar-row"><select class="select-control" id="asset-filter"><option value="all">Todas as categorias</option><option>Mapas</option><option>Tokens</option><option>Retratos</option><option>Outros</option></select><span class="tag">${state.assets.length} ARQUIVOS</span></div>${state.assets.length?`<div class="asset-grid">${state.assets.map(a=>`<article class="asset-card"><div class="asset-preview">${a.type?.startsWith('image/')?`<img src="${a.data}" alt="${escapeHtml(a.name)}">`:'▧'}</div><b>${escapeHtml(a.name)}</b><small>${escapeHtml(a.category)} · ${Math.round(a.size/1024)} KB</small><button class="text-button" data-delete-asset="${a.id}">Remover</button></article>`).join('')}</div>`:'<div class="empty-state"><b>Suas relíquias ficarão aqui</b>Importe mapas e imagens para usar na mesa. Os arquivos são guardados no armazenamento local do navegador.<br><button class="primary-btn" data-action="upload-asset">＋ Importar arquivo</button></div>'}<input id="asset-input" type="file" accept="image/*,.pdf,.txt" multiple hidden>`;}
  function renderSettings(){const root=$('#view-root');root.innerHTML=`${pageHead('Configurações','Controle os dados locais e o comportamento da mesa.')}<section class="settings-panel"><h3>Dados e privacidade</h3><p>O SEED salva campanhas, personagens, rolagens e arquivos no armazenamento deste navegador. Nada é enviado a um servidor externo. Para jogar com outras pessoas remotamente, será necessário conectar um servidor multiplayer que ainda não está configurado.</p><div class="settings-actions"><button class="secondary-btn" data-action="export-data">⇩ Exportar cópia JSON</button><button class="secondary-btn" data-action="import-data">⇧ Restaurar cópia</button><button class="danger-btn" data-action="clear-data">Apagar dados locais</button></div><input id="import-data-input" type="file" accept="application/json" hidden></section><section class="settings-panel"><h3>Preferências de mesa</h3><p>Ajuste a grade padrão. O tipo e o tamanho também podem ser configurados por mapa.</p><div class="settings-actions"><label class="field">Tamanho da célula <select class="select-control" id="setting-grid">${[32,48,64,80,96].map(n=>`<option ${state.settings.grid===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Grade padrão <select class="select-control" id="setting-grid-type"><option value="square" ${state.settings.gridType==='square'?'selected':''}>Quadrangular</option><option value="hex" ${state.settings.gridType==='hex'?'selected':''}>Hexagonal</option><option value="none">Sem grade</option></select></label></div></section><section class="settings-panel"><h3>Sobre o SEED</h3><p>Uma mesa virtual local-first e de código aberto em espírito: sem contas, APIs pagas ou dependências obrigatórias. Os dados permanecem neste navegador; faça exportações regulares como backup.</p></section>`;}
  function openModal(title,body,actions='',wide=false){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close-btn" data-close-modal aria-label="Fechar">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;$('.modal-backdrop',root).addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});const focus=$('input,textarea,select',root);if(focus)focus.focus();}
  function closeModal(){$('#modal-root').innerHTML='';}
  const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${escapeHtml(value)}" ${extra}></div>`;
  function createCampaign(existing){const c=existing||{};openModal(existing?'Editar campanha':'Nova campanha',`<form id="campaign-form"><div class="form-grid">${field('NOME DA CAMPANHA','name',c.name||'')}${field('AMBIENTAÇÃO / TOM','setting',c.setting||'Fantasia sombria')}<div class="field full"><label>DESCRIÇÃO</label><textarea name="description" placeholder="O que aguarda os aventureiros?">${escapeHtml(c.description||'')}</textarea></div><div class="field"><label>SISTEMA DE RPG</label><select name="systemId">${state.systems.map(s=>`<option value="${s.id}" ${(c.systemId||'freeform')===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field"><label>ESTADO</label><select name="status"><option ${!c.status||c.status==='EM ANDAMENTO'?'selected':''}>EM ANDAMENTO</option><option ${c.status==='Arquivada'?'selected':''}>Arquivada</option></select></div></div></form>`,`${existing?`<button class="danger-btn" data-delete-campaign="${c.id}" style="margin-right:auto">Excluir</button>`:''}<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-campaign="${c.id||''}">Salvar campanha</button>`);}
  function characterDraftFromForm(form,sourceSystemId,previous){const values=formObject(form),source=getSystem(sourceSystemId||values.systemId),attributes={},sheetData={...(previous?.sheetData||{})};(source.attributes||[]).forEach((name,index)=>{attributes[name]=values[`attr_${index}`]||'';});Object.entries(values).forEach(([key,value])=>{if(key.startsWith('sheet_'))sheetData[key.slice(6)]=value;});const fields=Object.fromEntries(Object.entries(values).filter(([key])=>!key.startsWith('attr_')&&!key.startsWith('sheet_')));return{...fields,attributes,sheetData};}
  function createCharacter(existing){const ch=existing||{},system=getSystem(ch.systemId||state.systems[0].id),dnd=system.sheetType==='dnd5e'||system.id==='dnd5e',data=ch.sheetData||{},campaignId=ch.campaignId||'';const attributes=(system.attributes||[]).map((name,index)=>`<label class="ability-field"><span>${escapeHtml(name)}</span><input name="attr_${index}" value="${escapeHtml(ch.attributes?.[name]??'')}" aria-label="${escapeHtml(name)}"></label>`).join('');const common=`${field('NOME','name',ch.name||'')}${field(dnd?'CLASSE / ARQUÉTIPO':'PAPEL / ARQUÉTIPO','role',ch.role||'Aventureiro')}${field('NÍVEL / MARCO','level',ch.level||'1')}${field('PONTOS DE VIDA ATUAIS','hp',ch.hp??10,'number')}${field('PONTOS DE VIDA MÁXIMOS','maxHp',ch.maxHp??10,'number')}<div class="field"><label>SISTEMA</label><select name="systemId" id="character-system">${state.systems.map(s=>`<option value="${s.id}" ${system.id===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field full"><label>CAMPANHA (OPCIONAL)</label><select name="campaignId"><option value="">Nenhuma</option>${state.campaigns.map(c=>`<option value="${c.id}" ${campaignId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div>`;let body=`<div class="sheet-intro"><b>Ficha flexível</b><span>Campos e atributos adaptados ao sistema selecionado.</span></div><div class="form-grid">${common}`;if(dnd){body+=`${field('RAÇA / ESPÉCIE','sheet_race',data.race||'')}${field('ANTECEDENTE','sheet_background',data.background||'')}${field('TENDÊNCIA','sheet_alignment',data.alignment||'')}${field('EXPERIÊNCIA (XP)','sheet_experience',data.experience||'','number')}<div class="field full"><label>ATRIBUTOS</label><div class="ability-grid">${attributes}</div><small class="field-hint">Registre os valores e modificadores conforme as regras da sua mesa.</small></div><div class="field full"><label>COMBATE E RECURSOS</label><div class="sheet-stat-grid">${field('CLASSE DE ARMADURA','sheet_armorClass',data.armorClass??10,'number')}${field('INICIATIVA','sheet_initiative',data.initiative??0,'number')}${field('DESLOCAMENTO','sheet_speed',data.speed??9)}${field('BÔNUS DE PROFICIÊNCIA','sheet_proficiencyBonus',data.proficiencyBonus||'+2')}${field('DADOS DE VIDA','sheet_hitDice',data.hitDice||'')}${field('INSPIRAÇÃO','sheet_inspiration',data.inspiration||'Não')}</div></div><div class="field full"><label>TESTES DE RESISTÊNCIA</label><div class="sheet-check-grid">${(system.attributes||[]).map((name,i)=>`<label>${escapeHtml(name)}<select name="sheet_save_${i}"><option value="">Sem proficiência</option><option value="prof" ${data[`save_${i}`]==='prof'?'selected':''}>Proficiente</option></select></label>`).join('')}</div></div><div class="field full"><label>PERÍCIAS</label><div class="sheet-check-grid">${(system.skills||[]).map((name,i)=>`<label>${escapeHtml(name)}<select name="sheet_skill_${i}"><option value="">Sem proficiência</option><option value="prof" ${data[`skill_${i}`]==='prof'?'selected':''}>Proficiente</option><option value="expert" ${data[`skill_${i}`]==='expert'?'selected':''}>Especialização</option></select></label>`).join('')}</div></div><div class="field full"><label>ATAQUES E CONJURAÇÃO</label><div class="sheet-stat-grid">${field('HABILIDADE DE CONJURAÇÃO','sheet_spellAbility',data.spellAbility||'')}${field('CD PARA RESISTIR','sheet_spellSaveDc',data.spellSaveDc||'')}${field('BÔNUS DE ATAQUE MÁGICO','sheet_spellAttackBonus',data.spellAttackBonus||'')}</div><textarea name="sheet_attacks" placeholder="Ataques, alcance, dano e observações">${escapeHtml(data.attacks||'')}</textarea><textarea name="sheet_spells" placeholder="Truques e magias conhecidos/preparados">${escapeHtml(data.spells||'')}</textarea></div><div class="field full"><label>EQUIPAMENTO E TESOURO</label><textarea name="sheet_equipment" placeholder="Armaduras, armas, itens e moedas">${escapeHtml(data.equipment||'')}</textarea></div><div class="field full"><label>CARACTERÍSTICAS E TRAÇOS</label><textarea name="sheet_features" placeholder="Traços de classe, raça e talentos">${escapeHtml(data.features||'')}</textarea></div>`;}else{body+=`<div class="field full"><label>ATRIBUTOS · valores livres</label><div class="ability-grid">${attributes}</div></div><div class="field full"><label>PERÍCIAS / CAMPOS DO SISTEMA</label><div class="sheet-check-grid">${(system.skills||[]).map((name,i)=>`<label>${escapeHtml(name)}<input name="sheet_skill_${i}" value="${escapeHtml(data[`skill_${i}`]||'')}" placeholder="Valor / anotação"></label>`).join('')}</div></div>`;}body+=`<div class="field full"><label>${dnd?'PERSONALIDADE, IDEIAIS, VÍNCULOS E DEFEITOS':'HISTÓRIA / NOTAS'}</label><textarea name="notes" placeholder="Motivações, laços, segredos...">${escapeHtml(ch.notes||'')}</textarea></div></div>`;openModal(dnd?'Ficha de personagem · fantasia d20':ch.id?'Editar personagem':'Novo personagem',`<form id="character-form" data-system-id="${system.id}" data-character-id="${ch.id||''}">${body}</form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-character="${ch.id||''}">Salvar ficha</button>`,true);}
  function createSystem(existing){const s=existing||{};openModal(existing?'Configurar sistema':'Novo sistema',`<form id="system-form"><div class="form-grid">${field('NOME','name',s.name||'')}${field('VERSÃO','version',s.version||'1.0')}<div class="field full"><label>DESCRIÇÃO</label><textarea name="description">${escapeHtml(s.description||'')}</textarea></div><div class="field full"><label>ATRIBUTOS (separados por vírgula)</label><input name="attributes" value="${escapeHtml((s.attributes||[]).join(', '))}" placeholder="Ex.: Vigor, Astúcia"></div><div class="field full"><label>PERÍCIAS / CAMPOS ADICIONAIS</label><input name="skills" value="${escapeHtml((s.skills||[]).join(', '))}" placeholder="Ex.: Sobrevivência, Ofício"></div><div class="field"><label>DADO PADRÃO INFORMATIVO</label><input name="dice" value="${escapeHtml(s.dice||'d20')}" placeholder="d20, d6... "></div></div></form><p style="font-size:9px;color:#8f8777">Os dados definidos aparecem como campos iniciais nas fichas. Fórmulas podem ser roladas diretamente na mesa.</p>`,`${existing&&!s.builtin?`<button class="danger-btn" data-delete-system="${s.id}" style="margin-right:auto">Excluir</button>`:''}<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-system="${s.id||''}">Salvar sistema</button>`);}

  // Each campaign owns a persisted tabletop, initiative order and local chat log.
  state.assets=state.assets||[];state.rolls=state.rolls||[];state.activity=state.activity||[];state.settings={grid:64,gridType:'square',...(state.settings||{})};
  state.campaigns.forEach(c=>{c.sessions=c.sessions||[];c.tabletop=c.tabletop||{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0};c.chat=c.chat||[];});
  function tabletopFor(c){if(!c)return null;c.tabletop=c.tabletop||{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0};c.tabletop.tokens=c.tabletop.tokens||[];c.tabletop.initiative=c.tabletop.initiative||[];c.tabletop.fogCells=c.tabletop.fogCells||[];c.chat=c.chat||[];return c.tabletop;}
  function currentCampaign(){return activeCampaign();}
  function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  function formObject(form){return Object.fromEntries(new FormData(form).entries());}
  function splitList(value){return value.split(',').map(x=>x.trim()).filter(Boolean);}
  function createSession(campaign){openModal('Agendar sessão',`<form id="session-form"><div class="form-grid">${field('NOME DA SESSÃO','name','Sessão de jogo')}${field('DATA','date','','date')}${field('HORÁRIO','time','','time')}<div class="field full"><label>NOTAS / PREPARAÇÃO</label><textarea name="notes" placeholder="Pauta, recados ou preparação"></textarea></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-session="${campaign.id}">Agendar</button>`);}
  function createToken(){const c=currentCampaign();if(!c){toast('Crie uma campanha antes de abrir a mesa.');navigate('campaigns');return;}openModal('Adicionar token',`<form id="token-form"><div class="form-grid">${field('NOME','name','Novo aventureiro')}<div class="field"><label>PERSONAGEM VINCULADO</label><select name="characterId"><option value="">Token livre</option>${state.characters.map(ch=>`<option value="${ch.id}">${escapeHtml(ch.name)}</option>`).join('')}</select></div><div class="field"><label>TIPO</label><select name="kind"><option value="hero">Aliado</option><option value="enemy">Adversário</option><option value="neutral">Neutro</option></select></div><div class="field"><label>INICIATIVA</label><input name="initiative" type="number" value="10"></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-token>Adicionar token</button>`);}
  function parseRoll(expression){const m=String(expression).trim().toLowerCase().match(/^(\d*)d(\d+)(?:\s*([+-])\s*(\d+))?$/);if(!m)throw new Error('Use uma fórmula como d20, 2d6+3 ou 1d100.');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[4]||0)*(m[3]==='-'?-1:1);if(count<1||count>100||sides<2||sides>10000||mod>100000||mod< -100000)throw new Error('Limites: até 100 dados, d2–d10000 e modificador de 100000.');const dice=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return{expression:String(expression).trim(),dice,mod,total:dice.reduce((a,b)=>a+b,0)+mod};}
  function recordRoll(expression,author='Mestre'){try{const r=parseRoll(expression);r.id=uid();r.time=Date.now();r.author=author;state.rolls.unshift(r);state.rolls=state.rolls.slice(0,100);const c=currentCampaign();if(c){c.chat=c.chat||[];c.chat.push({id:uid(),author,text:`rolou ${r.expression}: ${r.total}`,roll:true,time:r.time});c.chat=c.chat.slice(-100);}save();if(currentView==='tabletop')renderTabletop();else renderDashboard();return r;}catch(e){toast(e.message);return null;}}
  function diceModal(){const recent=state.rolls.slice(0,8);openModal('Rolar dados',`<form id="roll-form"><div class="field"><label>FÓRMULA</label><input name="formula" value="d20" placeholder="d20, 2d6+3" required></div></form><div class="roll-history">${recent.map(r=>`<div class="roll-item"><span>${escapeHtml(r.expression)} · ${new Date(r.time).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span><b>${r.total}</b></div>`).join('')||'<p class="muted">Suas rolagens aparecerão aqui.</p>'}</div>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-roll-modal>Rolar</button>`);}
  function renderTabletop(){const root=$('#view-root'),c=currentCampaign();if(!c){root.innerHTML=`<div class="empty-state"><b>A mesa precisa de uma campanha</b>Crie ou selecione uma campanha para abrir o mapa, tokens e combate.<br><button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button></div>`;return;}const t=tabletopFor(c),asset=state.assets.find(a=>a.id===t.mapAssetId);root.innerHTML=`<section class="tabletop-view"><div class="session-bar"><div class="session-title">${escapeHtml(c.name)} <small>· ${escapeHtml(getSystem(c.systemId).name)}</small></div><div class="session-tools"><button data-action="new-session" class="hide-mobile">◷ Sessão</button><button data-action="map-image" class="hide-mobile">▧ Mapa</button><button data-action="toggle-grid">Grade: ${t.gridType==='none'?'off':t.grid+'px'}</button><button data-action="add-token">＋ Token</button></div></div><div class="tabletop-layout"><div class="map-tools"><button class="map-tool ${activeTool==='select'?'active':''}" data-tool="select" title="Selecionar / mover">↖</button><button class="map-tool ${activeTool==='pan'?'active':''}" data-tool="pan" title="Mover mapa">✥</button><button class="map-tool ${activeTool==='token'?'active':''}" data-tool="token" title="Adicionar token">♙</button><button class="map-tool ${activeTool==='measure'?'active':''}" data-tool="measure" title="Medir distância">↔</button><button class="map-tool ${activeTool==='fog'?'active':''}" data-tool="fog" title="Ocultar área (pinte no mapa)">▧</button><button class="map-tool ${activeTool==='reveal'?'active':''}" data-tool="reveal" title="Revelar área">☼</button><div class="tool-divider"></div><button class="map-tool" data-action="map-image" title="Escolher mapa">▧</button><button class="map-tool" data-action="toggle-grid" title="Alternar grade">▦</button><button class="map-tool" data-action="center-map" title="Centralizar">⌖</button></div><div class="map-workspace"><canvas id="map-canvas" class="map-canvas" aria-label="Mapa da mesa"></canvas><div class="map-hud"><span class="hud-chip">${asset?escapeHtml(asset.name):'MAPA SEM IMAGEM'}</span><span class="hud-chip">${t.gridType==='none'?'SEM GRADE':t.gridType==='hex'?'GRADE HEXAGONAL':`GRADE ${t.grid}px`}</span></div><div class="map-zoom"><button data-zoom="out">−</button><button data-zoom="in">＋</button><button data-action="center-map">⌖</button></div></div><aside class="map-right"><div class="right-tabs"><button class="active" data-tab="combat">Combate</button><button data-tab="tokens">Tokens</button><button data-tab="notes">Notas</button></div><div class="right-content" id="tabletop-panel"></div></aside></div><div class="bottom-dock"><section class="chat-panel"><div class="dock-heading">CHAT DA MESA <small>Somente neste dispositivo</small></div><div class="chat-log" id="chat-log">${(c.chat||[]).slice(-20).map(m=>`<p class="chat-line"><b>${escapeHtml(m.author||'Mestre')}</b><span class="${m.roll?'roll-text':''}">${escapeHtml(m.text)}</span></p>`).join('')||'<p class="chat-line">A conversa da mesa começa aqui.</p>'}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Mensagem ou /roll 2d6+2" autocomplete="off"><button>Enviar</button></form></section><section class="dice-panel"><div class="dock-heading">✦ &nbsp; ROLAGEM RÁPIDA</div><div class="quick-rolls">${[4,6,8,10,12,20].map(n=>`<button data-quick-roll="d${n}">d${n}</button>`).join('')}</div><form class="inline-roll" id="inline-roll"><input name="formula" value="d20" aria-label="Fórmula de dados"><button>Rolar</button></form><div class="dice-last">${state.rolls[0]?`${escapeHtml(state.rolls[0].expression)} = ${state.rolls[0].total}`:'Nenhuma rolagem ainda'}</div></section></div></section>`;renderTabletopPanel();initCanvas();}
  let tabletopTab='combat',activeTool='select',canvasObserver;
  function renderTabletopPanel(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c),panel=$('#tabletop-panel');if(!panel)return;if(tabletopTab==='combat'){const order=t.initiative||[],cur=order[t.turnIndex||0];panel.innerHTML=`<div class="panel-heading">Iniciativa <button data-action="start-combat" title="Iniciar combate">⚄</button></div>${cur?`<div class="turn-card"><small>RODADA ${t.round||1} · TURNO ATUAL</small><b>${escapeHtml(cur.name)}</b><div class="turn-actions"><button class="secondary-btn" data-action="next-turn">Próximo turno →</button><button class="secondary-btn" data-action="end-combat">Encerrar</button></div></div>`:''}<div class="combat-controls"><button class="secondary-btn" data-action="start-combat">⚄ Iniciar / rolar iniciativa</button><button class="secondary-btn" data-action="add-token">＋</button></div>${order.length?`<div class="initiative-list-mobile">${order.map((x,i)=>`<div class="initiative-row ${i===(t.turnIndex||0)?'turn-current':''}"><span class="initiative-number">${x.score}</span><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':'Aliado'}</small></span><button class="text-button" data-remove-initiative="${x.id}">×</button></div>`).join('')}</div>`:'<div class="combat-empty">Adicione tokens e role a iniciativa para acompanhar o combate.</div>'}`;}else if(tabletopTab==='tokens'){panel.innerHTML=`<div class="panel-heading">Tokens no mapa <button data-action="add-token">＋</button></div>${t.tokens.length?t.tokens.map(x=>`<div class="initiative-row"><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':x.kind==='hero'?'Aliado':'Neutro'}</small></span><button class="text-button" data-remove-token="${x.id}">×</button></div>`).join(''):'<div class="combat-empty">Nenhum token. Use ＋ para adicionar.</div>'}<di