74: -- Campaign payload is visible to the owner and approved members. Approved players
75: -- may update shared play state; only the owner may create or delete a campaign.
76: drop policy if exists seed_campaigns_read_members on public.seed_campaigns;
77: create policy seed_campaigns_read_members on public.seed_campaigns
78:   for select to authenticated using (
79:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
80:   );
81: drop policy if exists seed_campaigns_insert_owner on public.seed_campaigns;
82: create policy seed_campaigns_insert_owner on public.seed_campaigns
83:   for insert to authenticated with check (
84:     owner_id = (select auth.uid()) and exists (
85:       select 1 from public.seed_profiles p
86:       where p.user_id = (select auth.uid()) and p.app_role = 'master'
87:     )
88:   );
89: drop policy if exists seed_campaigns_update_members on public.seed_campaigns;
90: create policy seed_campaigns_update_members on public.seed_campaigns
91:   for update to authenticated using (
92:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
93:   ) with check (
94:     owner_id = (select auth.uid()) or public.seed_is_active_member(id)
95:   );
96: drop policy if exists seed_campaigns_delete_owner on public.seed_campaigns;
97: create policy seed_campaigns_delete_owner on public.seed_campaigns
98:   for delete to authenticated using (owner_id = (select auth.uid()));
