167: create or replace function public.seed_approve_member(p_campaign_id text, p_user_id uuid)
168: returns void
169: language plpgsql security definer set search_path = ''
170: as $$
171: begin
172:   if not exists (select 1 from public.seed_campaigns c
173:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
174:     raise exception 'Somente o Mestre da campanha pode aprovar participantes';
175:   end if;
176:   update public.seed_campaign_members set status = 'active'
177:   where campaign_id = p_campaign_id and user_id = p_user_id and status = 'pending';
178:   if not found then raise exception 'Solicitação não encontrada'; end if;
179: end;
180: $$;
