  const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${escapeHtml(value)}" ${extra}></div>`;
  function createCampaign(existing){const c=existing||{};openModal(existing?'Editar campanha':'Nova campanha',`<form id="campaign-form"><div class="form-grid">${field('NOME DA CAMPANHA','name',c.name||'')}${field('AMBIENTAÇÃO / TOM','setting',c.setting||'Fantasia sombria')}<div class="field full"><label>DESCRIÇÃO</label><textarea name="description" placeholder="O que aguarda os aventureiros?">${escapeHtml(c.description||'')}</textarea></div><div class="field"><label>SISTEMA DE RPG</label><select name="systemId">${state.systems.map(s=>`<option value="${s.id}" ${(c.systemId||'freeform')===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field"><label>ESTADO</label><select name="status"><option ${!c.status||c.status==='EM ANDAMENTO'?'selected':''}>EM ANDAMENTO</option><option ${c.status==='Arquivada'?'selected':''}>Arquivada</option></select></div></div></form>`,`${existing?`<button class="danger-btn" data-delete-campaign="${c.id}" style="margin-right:auto">Excluir</button>`:''}<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-campaign="${c.id||''}">Salvar campanha</button>`);}
  function characterDraftFromForm(form,sourceSystemId,previous){const values=formObject(form),source=getSystem(sourceSystemId||values.systemId),attributes={},sheetData={...(previous?.sheetData||{})};(source.attributes||[]).forEach((name,index)=>{attributes[name]=values[`attr_${index}`]||'';});Object.entries(values).forEach(([key,value])=>{if(key.startsWith('sheet_'))sheetData[key.slice(6)]=value;});const fields=Object.fromEntries(Object.entries(values).filter(([key])=>!key.startsWith('attr_')&&!key.startsWith('sheet_')));return{...fields,attributes,sheetData};}
  function createCharacter(existing){const ch=existing||{},system=getSystem(ch.systemId||state.systems[0].id),dnd=system.sheetType==='dnd5e'||system.id==='dnd5e',data=ch.sheetData||{},campaignId=ch.campaignId||'';const attributes=(system.attributes||[]).map((name,index)=>`<label class="ability-field"><span>${escapeHtml(name)}</span><input name="attr_${index}" value="${escapeHtml(ch.attributes?.[name]??'')}" aria-label="${escapeHtml(name)}"></label>`).join('');const common=`${field('NOME','name',ch.name||'')}${field(dnd?'CLASSE / ARQUÉTIPO':'PAPEL / ARQUÉTIPO','role',ch.role||'Aventureiro')}${field('NÍVEL / MARCO','level',ch.level||'1')}${field('PONTOS DE VIDA ATUAIS','hp',ch.hp??10,'number')}${field('PONTOS DE VIDA MÁXIMOS','maxHp',ch.maxHp??10,'number')}<div class="field"><label>SISTEMA</label><select name="systemId" id="character-system">${state.systems.map(s=>`<option value="${s.id}" ${system.id===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field full"><label>CAMPANHA (OPCIONAL)</label><select name="campaignId"><option value="">Nenhuma</option>${state.campaigns.map(c=>`<option value="${c.id}" ${campaignId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div>`;let body=`<div class="sheet-intro"><b>Ficha flexível</b><span>Campos e atributos adaptados ao sistema selecionado.</span></div><div class="form-grid">${common}`;if(dnd){body+=`${field('RAÇA / ESPÉCIE','sheet_race',data.race||'')}${field('ANTECEDENTE','sheet_background',data.background||'')}${field('TENDÊNCIA','sheet_alignment',data.alignment||'')}${field('EXPERIÊNCIA (XP)','sheet_experience',data.experience||'','number')}<div class="field full"><label>ATRIBUTOS</label><div class="ability-grid">${attributes}</div><small class="field-hint">Registre os valores e modificadores conforme as regras da sua mesa.</small></div><div class="field full"><label>COMBATE E RECURSOS</label><div class="sheet-stat-grid">${field('CLASSE DE ARMADURA','sheet_a