  let tabletopTab='combat',activeTool='select',canvasObserver;
  function renderTabletopPanel(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c),panel=$('#tabletop-panel');if(!panel)return;if(tabletopTab==='combat'){const order=t.initiative||[],cur=order[t.turnIndex||0];panel.innerHTML=`<div class="panel-heading">Iniciativa <button data-action="start-combat" title="Iniciar combate">⚄</button></div>${cur?`<div class="turn-card"><small>RODADA ${t.round||1} · TURNO ATUAL</small><b>${escapeHtml(cur.name)}</b><div class="turn-actions"><button class="secondary-btn" data-action="next-turn">Próximo turno →</button><button class="secondary-btn" data-action="end-combat">Encerrar</button></div></div>`:''}<div class="combat-controls"><button class="secondary-btn" data-action="start-combat">⚄ Iniciar / rolar iniciativa</button><button class="secondary-btn" data-action="add-token">＋</button></div>${order.length?`<div class="initiative-list-mobile">${order.map((x,i)=>`<div class="initiative-row ${i===(t.turnIndex||0)?'turn-current':''}"><span class="initiative-number">${x.score}</span><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':'Aliado'}</small></span><button class="text-button" data-remove-initiative="${x.id}">×</button></div>`).join('')}</div>`:'<div class="combat-empty">Adicione tokens e role a iniciativa para acompanhar o combate.</div>'}`;}else if(tabletopTab==='tokens'){panel.innerHTML=`<div class="panel-heading">Tokens no mapa <button data-action="add-token">＋</button></div>${t.tokens.length?t.tokens.map(x=>`<div class="initiative-row"><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':x.kind==='hero'?'Aliado':'Neutro'}</small></span><button class="text-button" data-remove-token="${x.id}">×</button></div>`).join(''):'<div class="combat-empty">Nenhum token. Use ＋ para adicionar.</div>'}<di