  function initCanvas(){const canvas=$('#map-canvas');if(!canvas)return;const c=currentCampaign(),t=tabletopFor(c),ctx=canvas.getContext('2d');let bgImage=null,measureStart=null,measureEnd=null,measurePointer=null;const asset=state.assets.find(a=>a.id===t.mapAssetId);if(asset?.type?.startsWith('image/')){bgImage=new Image();bgImage.onload=draw;bgImage.src=asset.data;}let w=0,h=0;function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);w=rect.width;h=rect.height;canvas.width=Math.max(1,w*dpr);canvas.height=Math.max(1,h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}function draw(){if(!w||!h)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#25231d';ctx.fillRect(0,0,w,h);if(bgImage?.complete&&bgImage.naturalWidth){const scale=Math.max(w/bgImage.naturalWidth,h/bgImage.naturalHeight)*t.zoom;const iw=bgImage.naturalWidth*scale,ih=bgImage.naturalHeight*scale;ctx.drawImage(bgImage,(w-iw)/2+t.panX,(h-ih)/2+t.panY,iw,ih);}else{ctx.fillStyle='#302c22';for(let i=0;i<30;i++){const x=((i*137)%Math.max(w,1)),y=((i*83)%Math.max(h,1));ctx.globalAlpha=.12;ctx.beginPath();ctx.arc(x,y,(i%4)+1,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
      if(t.gridType!=='none'){const g=Number(t.grid)||64;ctx.strokeStyle='#d8c99a35';ctx.lineWidth=1;ctx.beginPath();if(t.gridType==='hex'){const dx=g,dy=g*.866;for(let row=-2;row<h/dy+3;row++)for(let col=-2;col<w/dx+3;col++){const x=col*dx+(row%2)*dx/2+t.panX%dx,y=row*dy+t.panY%dy;for(let k=0;k<6;k++){const a=Math.PI/3*k;const px=x+Math.cos(a)*g/2,py=y+Math.sin(a)*g/2;k?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();}}else{const ox=((t.panX%g)+g)%g,oy=((t.panY%g)+g)%g;for(let x=ox;x<w;x+=g){ctx.moveTo(x,0);ctx.lineTo(x,h);}for(let y=oy;y<h;y+=g){ctx.moveTo(0,y);ctx.lineTo(w,y);}}ctx.stroke();}
      (t.tokens||[]).forEach(tok=>{const x=tok.x,y=tok.y,r=22;ctx.save();ctx.shadowColor=tok.kind==='enemy'?'#a64d46':'#d0ac57';ctx.shadowBlur=12;ctx.fillStyle=tok.kind==='enemy'?'#63352f':tok.kind==='neutral'?'#3c4a49':'#65532f';ctx.strokeStyle=tok.kind==='enemy'?'#c16f60':'#d3b86e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#f0e5c9';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText((tok.name||'?').slice(0,1).toUpperCase(),x,y);ctx.fillStyle='#eee2c9';ctx.font='10px sans-serif';ctx.fillText(tok.name,x,y+r+13);ctx.restore();});const fogSize=t.gridType==='none'?48:Number(t.grid)||64;ctx.fillStyle='rgba(9,10,9,.94)';(t.fogCells||[]).forEach(key=>{const [col,row]=key.split(',').map(Number);ctx.fillRect(col*fogSize+t.panX,row*fogSize+t.panY,fogSize,fogSize);});if(measureStart){ctx.save();ctx.strokeStyle='#e6c875';ctx.lineWidth=2;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(measureStart.x,measureStart.y);if(measureEnd)ctx.lineTo(measureEnd.x,measureEnd.y);else if(measurePointer)ctx.lineTo(measurePointer.x,measurePointer.y);ctx.stroke();ctx.setLineDash([]);const end=measureEnd||measurePointer;if(end){const dist=Math.hypot(end.x-measureStart.x,end.y-measureStart.y),units=t.gridType==='none'?Math.round(dist/48*5):Math.round(dist/(Number(t.grid)||64)*5);const label=`${units} pés`;const mx=(measureStart.x+end.x)/2,my=(measureStart.y+end.y)/2;ctx.font='12px sans-serif';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#171612';ctx.fillRect(mx-31,my-20,62,18);ctx.fillStyle='#f0dfa9';ctx.fillText(label,mx,my-5);}ctx.restore();}}
    resize();if(canvasObserver)canvasObserver.disconnect();canvasObserver=new ResizeObserver(resize);canvasObserver.observe(canvas.parentElement);let drag=null;const pos=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};};const paintFog=(p,hide,from)=>{const size=t.gridType==='none'?48:Number(t.grid)||64,steps=from?Math.max(1,Math.ceil(Math.hypot(p.x-from.x,p.y-from.y)/(size/3))):1;for(let i=1;i<=steps;i++){const x=from?from.x+(p.x-from.x)*i/steps:p.x,y=from?from.y+(p.y-from.y)*i/steps:p.y,col=Math.floor((x-t.panX)/size),row=Math.floor((y-t.panY)/size),key=`${col},${row}`;if(hide&&!t.fogCells.includes(key))t.fogCells.push(key);if(!hide)t.fogCells=t.fogCells.filter(cell=>cell!==key);}};canvas.onpointerdown=e=>{const p=pos(e),hit=[...t.tokens].reverse().find(tok=>Math.hypot(tok.x-p.x,tok.y-p.y)<25);if(activeTool==='token'){addTokenAt(p.x,p.y);return;}if(activeTool==='fog'||activeTool==='reveal'){drag={kind:activeTool,p};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');paintFog(p,activeTool==='fog');draw();return;}if(activeTool==='measure'){if(!measureStart||measureEnd){measureStart=p;measureEnd=null;}else measureEnd=p;measurePointer=p;canvas.setPointerCapture(e.pointerId);draw();return;}if(activeTool==='select'&&hit){drag={kind:'token',token:hit,p};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');}else if(activeTool==='pan'){drag={kind:'pan',p,px:t.panX,py:t.panY};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');}};canvas.onpointermove=e=>{const p=pos(e);if(activeTool==='measure'&&measureStart&&!measureEnd){measurePointer=p;draw();}if(!drag)return;if(drag.kind==='token'){drag.token.x=p.x;drag.token.y=p.y;}else if(drag.kind==='pan'){t.panX=drag.px+p.x-drag.p.x;t.panY=drag.py+p.y-drag.p.y;}else if(drag.kind==='fog'||drag.kind==='reveal'){paintFog(p,drag.kind==='fog',drag.p);drag.p=p;}draw();};canvas.onpointerup=()=>{if(drag?.kind==='token'){const g=t.grid||64;if(t.gridType!=='none'){drag.token.x=Math.round(drag.token.x/g)*g+g/2;drag.token.y=Math.round(drag.token.y/g)*g+g/2;}save();renderTabletopPanel();}else if(drag)save();else if(activeTool==='fog'||activeTool==='reveal')save();drag=null;canvas.classList.remove('dragging');};canvas.onpointercancel=canvas.onpointerup;canvas.onwheel=e=>{e.preventDefault();t.zoom=Math.max(.4,Math.min(2.5,t.zoom*(e.deltaY<0?1.1:.9)));save();draw();};function addTokenAt(x,y){const token={id:uid(),name:'Novo token',kind:'hero',x,y};t.tokens.push(token);save();draw();renderTabletopPanel();openTokenEditor(token);}}
  function openTokenEditor(token){openModal('Nomear token',`<form id="token-name-form">${field('NOME','name',token.name)}<div class="field"><label>TIPO</label><select name="kind"><option value="hero" ${token.kind==='hero'?'selected':''}>Aliado</option><option value="enemy" ${token.kind==='enemy'?'selected':''}>Adversário</option><option value="neutral" ${token.kind==='neutral'?'selected':''}>Neutro</option></select></div></form>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-save-token-name="${token.id}">Salvar</button>`);}

  function showMapPicker(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c);openModal('Escolher mapa',`<div class="field"><label>IMAGEM DA BIBLIOTECA</label><select id="map-asset-select"><option value="">Mapa sem imagem</option>${state.assets.filter(a=>a.type?.startsWith('image/')).map(a=>`<option value="${a.id}" ${a.id===t.mapAssetId?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></div><p class="muted">Importe imagens pela Biblioteca para usá-las como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-map>Aplicar mapa</button>`);}
  function chooseUpload(category='Outros'){const input=document.createElement('input');input.type='file';input.accept='image/*,.pdf,.txt';input.multiple=true;input.onchange=async()=>{for(const file of [...input.files]){if(file.size>1500000){toast(`${file.name}: limite local de 1,5 MB por arquivo.`);continue;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});state.assets.push({id:uid(),name:file.name,type:file.type||'application/octet-stream',size:file.size,category,data});}catch{toast(`Não foi possível ler ${file.name}.`);}}save();render();if(state.assets.length)logActivity('Novos arquivos foram adicionados à biblioteca.');};input.click();}
  function safeImport(data){if(!data||typeof data!=='object'||!Array.isArray(data.campaigns)||!Array.isArray(data.characters)||!Array.isArray(data.systems))throw new Error('Arquivo de backup inválido.');const base=defaults();state={...base,...data,assets:Array.isArray(data.assets)?data.assets:[],rolls:Array.isArray(data.rolls)?data.rolls:[],activity:Array.isArray(data.activity)?data.activity:[],settings:{...base.settings,...(data.settings||{})}};state.campaigns.forEach(c=>{c.sessions=c.sessions||[];c.tabletop=c.tabletop||{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0};c.chat=c.chat||[];});save();render();toast('Cópia restaurada com sucesso.');}
  function handleAction(action){const c=currentCampaign(),t=c&&tabletopFor(c);switch(action){case'create-campaign':createCampaign();break;case'create-character':createCharacter();break;case'create-system':createSystem();break;case'new-session':if(c)createSession(c);else toast('Crie uma campanha primeiro.');break;case'add-token':createToken();break;case'add-character-token':if(!c)return;{const ch=state.characters[0];if(!ch){toast('Crie um personagem antes de vinculá-lo.');return;}const token={id:uid(),name:ch.name,kind:'hero',x:160+(t.tokens.length%4)*64,y:140+Math.floor(t.tokens.length/4)*64,characterId:ch.id};t.tokens.push(token);save();renderTabletop();}break;case'toggle-grid':if(t){t.gridType=t.gridType==='none'?'square':t.gridType==='square'?'hex':'none';save();renderTabletop();}break;case'map-image':showMapPicker();break;case'center-map':if(t){t.panX=0;t.panY=0;t.zoom=1;save();renderTabletop();}break;case'save-notes':if(c){t.notes=$('#table-notes')?.value||'';save();toast('Notas salvas neste dispositivo.');}break;case'start-combat':if(!t||!t.tokens.length){toast('Adicione ao menos um token antes de iniciar o combate.');return;}t.initiative=t.tokens.map(x=>({...x,score:Number(x.initiative)||1+Math.floor(Math.random()*20)})).sort((a,b)=>b.score-a.score);t.turnIndex=0;t.round=1;save();renderTabletopPanel();break;case'next-turn':if(t?.initiative.length){t.turnIndex=(t.turnIndex+1)%t.initiative.length;if(t.turnIndex===0)t.round=(t.round||1)+1;save();renderTabletopPanel();}break;case'end-combat':if(t){t.initiative=[];t.turnIndex=0;t.round=1;save();renderTabletopPanel();}break;case'upload-asset':openModal('Importar para biblioteca',`<div class="field"><label>CATEGORIA</label><select id="upload-category"><option>Mapas</option><option>Tokens</option><option>Retratos</option><option selected>Outros</option></select></div><p class="muted">Arquivos de até 1,5 MB são guardados localmente. Imagens podem ser usadas como mapa.</p>`,`<button class="secondary-btn" data-close-mod