function renderCampaigns(){const root=$('#view-root'),cloud=window.SEED_CLOUD,identity=cloud?.identity,canCreate=!cloud?.configured||identity?.profile?.app_role==='master';root.innerHTML=`${pageHead('Campanhas','Seus mundos, histórias e grupos em um único lugar.',canCreate?'<button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button>':'')}<div class="toolbar-row"><div class="search-box"><input id="campaign-search" placeholder="Buscar campanha..." /></div><select class="select-control" id="campaign-filter"><option value="all">Todas as campanhas</option><option value="active">Em andamento</option><option value="archived">Arquivadas</option></select></div>${identity?`<form id="cloud-join-form" class="cloud-join-form"><label for="cloud-invite-token">Entrar em uma campanha</label><input id="cloud-invite-token" name="inviteToken" placeholder="Cole aqui o código de convite" required><button class="secondary-btn" type="submit">Solicitar participação</button><small>O Mestre precisará aprovar sua solicitação.</small></form>${state.cloudRequests?.length?`<div class="cloud-pending-list"><b>Solicitações aguardando aprovação</b>${state.cloudRequests.map(request=>`<span>Campanha ${escapeHtml(request.campaign_id)}</span>`).join('')}</div>`:''}<div class="list-grid" id="campaign-list">${state.campaigns.length?state.campaigns.map(c=>{const owner=c._seedAccess==='owner',cloudMember=c._seedAccess==='member',pending=c._seedAccess==='pending';return `<article class="campaign-tile" ${pending?'':'data-open-campaign="'+escapeHtml(c.id)+'"'}>${art(c.rune||'✧',c.status||'EM ANDAMENTO')}<div class="tile-body"><h3>${escapeHtml(c.name)}${pending?' · solicitação pendente':''}</h3><p>${escapeHtml(c.description||'Sem descrição. Abra para configurar a campanha.')}</p><div class="campaign-meta"><span>${escapeHtml(getSystem(c.systemId).name)}</span><span>${(c.sessions||[]).length} sessões</span></div><div class="tile-actions">${!pending?`<button class="secondary-btn" data-enter="${c.id}">Abrir mesa</button>`:''}${(!cloud?.configured||owner)?`<button class="secondary-btn" data-edit-campaign="${c.id}">Editar</button>`:''}${!pending?`<button class="secondary-btn" data-session="${c.id}">＋ Sessão</button>`:''}${owner?`<button class="secondary-btn" data-members="${c.id}">Participantes</button>`:''}${cloudMember?'<span class="tag">JOGADOR</span>':''}</div></div></article>`;}).join(''):`<div class="empty-state" style="grid-column:1/-1"><b>Nenhuma campanha encontrada</b>${canCreate?'Inicie uma campanha para preparar sua mesa.':'Use um convite para solicitar acesso a uma campanha.'}<br>${canCreate?'<button class="primary-btn" data-action="create-campaign">＋ Criar campanha</button>':''}</div>`}</div>`;}
function handleAction(action){const c=currentCampaign(),t=c&&tabletopFor(c);switch(action){case'create-campaign':createCampaign();break;case'create-character':createCharacter();break;case'create-system':createSystem();break;case'new-session':if(c)createSession(c);else toast('Crie uma campanha primeiro.');break;case'add-token':createToken();break;case'add-character-token':if(!c)return;{const ch=state.characters[0];if(!ch){toast('Crie um personagem antes de vinculá-lo.');return;}const token={id:uid(),name:ch.name,kind:'hero',x:160+(t.tokens.length%4)*64,y:140+Math.floor(t.tokens.length/4)*64,characterId:ch.id};t.tokens.push(token);save();renderTabletop();}break;case'toggle-grid':if(t){t.gridType=t.gridType==='none'?'square':t.gridType==='square'?'hex':'none';save();renderTabletop();}break;case'map-image':showMapPicker();break;case'center-map':if(t){t.panX=0;t.panY=0;t.zoom=1;save();renderTabletop();}break;case'save-notes':if(c){t.notes=$('#table-notes')?.value||'';save();toast('Notas salvas neste dispositivo.');}break;case'start-combat':if(!t||!t.tokens.length){toast('Adicione ao menos um token antes de iniciar o combate.');return;}t.initiative=t.tokens.map(x=>({...x,score:Number(x.initiative)||1+Math.floor(Math.random()*20)})).sort((a,b)=>b.score-a.score);t.turnIndex=0;t.round=1;save();renderTabletopPanel();break;case'next-turn':if(t?.initiative.length){t.turnIndex=(t.turnIndex+1)%t.initiative.length;if(t.turnIndex===0)t.round=(t.round||1)+1;save();renderTabletopPanel();}break;case'end-combat':if(t){t.initiative=[];t.turnIndex=0;t.round=1;save();renderTabletopPanel();}break;case'upload-asset':openModal('Importar para biblioteca',`<div class="field"><label>CATEGORIA</label><select id="upload-category"><option>Mapas</option><option>Tokens</option><option>Retratos</option><option selected>Outros</option></select></div><p class="muted">Arquivos de até 1,5 MB são guardados localmente. Imagens podem ser usadas como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-start-upload>Escolher arquivo</button>`);break;case'export-data':download('seed-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));break;case'import-data':{const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{safeImport(JSON.parse(reader.result));}catch(e){toast(e.message||'Não foi possível restaurar o arquivo.');}};reader.readAsText(file);};input.click();}break;case'clear-data':if(confirm('Apagar todas as campanhas, personagens, rolagens e arquivos locais? Esta ação não pode ser desfeita.')){state=defaults();save();navigate('dashboard');toast('Dados locais apagados.');}break;}}

document.addEventListener('click',e=>{const target=e.target.closest('button,[data-open-campaign]');if(!target)return;if(target.dataset.view){navigate(target.dataset.view);return;}if(target.dataset.nav){navigate(target.dataset.nav);return;}if(target.id==='mobile-menu'){$('#sidebar').classList.toggle('open');return;}if(target.id==='quick-dice'){diceModal();return;}if(target.id==='top-create'){createCampaign();return;}if(target.hasAttribute('data-close-modal')){closeModal();return;}if(target.dataset.action){handleAction(target.dataset.action);return;}if(target.dataset.openCampaign){state.activeCampaign=target.dataset.openCampaign;save();navigate('tabletop');return;}if(target.dataset.enter){state.activeCampaign=target.dataset.enter;save();navigate('tabletop');return;}if(target.dataset.editCampaign){createCampaign(campaignById(target.dataset.editCampaign));return;}if(target.dataset.session){const campaign=campaignById(target.dataset.session);if(campaign)createSession(campaign);return;}if(target.dataset.editCharacter){const ch=state.characters.find(x=>x.id===target.dataset.editCharacter);if(ch)createCharacter(ch);return;}if(target.dataset.editSystem){const system=state.systems.find(x=>x.id===target.dataset.editSystem);if(system)createSystem(system);return;}if(target.dataset.deleteCampaign){if(confirm('Excluir esta campanha e suas sessões, chat e mapa?')){const id=target.dataset.deleteCampaign;state.campaigns=state.campaigns.filter(x=>x.id!==id);if(state.activeCampaign===id)state.activeCampaign=state.campaigns[0]?.id||null;closeModal();save();render();}return;}if(target.dataset.deleteSystem){if(confirm('Excluir este sistema? Campanhas e personagens vinculados usarão outro sistema.')){const id=target.dataset.deleteSystem;state.systems=state.systems.filter(x=>x.id!==id);state.campaigns.forEach(x=>{if(x.systemId===id)x.systemId=state.systems[0]?.id;});state.characters.forEach(x=>{if(x.systemId===id)x.systemId=state.systems[0]?.id;});closeModal();save();render();}return;}if(target.dataset.saveCampaign!==undefined){const form=$('#campaign-form'),v=formObject(form),id=target.dataset.saveCampaign; if(!v.name.trim()){toast('Informe o nome da campanha.');return;}let c=id?campaignById(id):null;if(c)Object.assign(c,v);else{c={id:uid(),...v,players:[],sessions:[],chat:[],tabletop:{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0}};state.campaigns.unshift(c);state.activeCampaign=c.id;}closeModal();save();logActivity(`${id?'Campanha atualizada':'Nova campanha criada'}: ${c.name}.`);render();return;}if(target.dataset.saveCharacter!==undefined){const form=$('#character-form'),id=target.dataset.saveCharacter,previous=id?state.characters.find(x=>x.id===id):null,v=characterDraftFromForm(form,form.dataset.systemId,previous);if(!(v.name||'').trim()){toast('Informe o nome do personagem.');return;}const campaign=campaignById(v.campaignId),ch={...previous,...v,id:id||uid(),hp:Number(v.hp)||0,maxHp:Number(v.maxHp)||1,attributes:v.attributes,sheetData:v.sheetData,campaignName:campaign?.name||'',notes:v.notes||''};if(id)state.characters=state.characters.map(x=>x.id===id?ch:x);else state.characters.unshift(ch);closeModal();save();logActivity(`Ficha salva: ${ch.name}.`);render();return;}if(target.dataset.saveSystem!==undefined){const form=$('#system-form'),v=formObject(form),id=target.dataset.saveSystem;if(!v.name.trim()){toast('Informe o nome do sistema.');return;}const s={id:id||uid(),name:v.name.trim(),version:v.version||'1.0',description:v.description||'',attributes:splitList(v.attributes||''),skills:splitList(v.skills||''),dice:v.dice||'d20',builtin:id?getSystem(id).builtin:false};if(id)state.systems=state.systems.map(x=>x.id===id?s:x);else state.systems.push(s);closeModal();save();render();return;}if(target.dataset.saveSession!==undefined){const c=campaignById(target.dataset.saveSession),v=formObject($('#session-form'));if(c){c.sessions.push({id:uid(),...v,status:'Agendada'});closeModal();save();logActivity(`Sessão agendada para ${c.name}.`);render();}return;}if(target.hasAttribute('data-save-token')){const v=formObject($('#token-form')),t=tabletopFor(currentCampaign());if(t){t.tokens.push({id:uid(),name:v.name||'Token',kind:v.kind,initiative:Number(v.initiative)||0,x:160+(t.tokens.length%4)*64,y:140+Math.floor(t.tokens.length/4)*64,characterId:v.characterId});closeModal();save();renderTabletop();}return;}if(target.dataset.saveTokenName){const token=tabletopFor(currentCampaign())?.tokens.find(x=>x.id===target.dataset.saveTokenName),v=formObject($('#token-name-form'));if(token){token.name=v.name||'Token';token.kind=v.kind;closeModal();save();renderTabletop();}return;}if(target.hasAttribute('data-save-map')){const t=tabletopFor(currentCampaign());if(t){t.mapAssetId=$('#map-asset-select')?.value||null;save();closeModal();renderTabletop();}return;}if(target.hasAttribute('data-start-upload')){const category=$('#upload-category')?.value||'Outros';closeModal();chooseUpload(category);return;}if(target.dataset.removeToken){const t=tabletopFor(currentCampaign());if(t){t.tokens=t.tokens.filter(x=>x.id!==target.dataset.removeToken);t.initiative=t.initiative.filter(x=>x.id!==target.dataset.removeToken);save();renderTabletop();}return;}if(target.dataset.removeInitiative){const t=tabletopFor(currentCampaign());if(t){t.initiative=t.initiative.filter(x=>x.id!==target.dataset.removeInitiative);t.turnIndex=0;save();renderTabletopPanel();}return;}if(target.dataset.deleteAsset){state.assets=state.assets.filter(x=>x.id!==target.dataset.deleteAsset);state.campaigns.forEach(c=>{if(c.tabletop?.mapAssetId===target.dataset.deleteAsset)c.tabletop.mapAssetId=null;});save();render();return;}if(target.dataset.tab){tabletopTab=target.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===target));renderTabletopPanel();return;}if(target.dataset.tool){activeTool=target.dataset.tool;const cursor=activeTool==='token'||activeTool==='fog'||activeTool==='reveal'