/* Supabase auth and campaign access for SEED. The browser only uses the public anon key. */
(() => {
  'use strict';
  const config = window.SEED_SUPABASE_CONFIG || {};
  const configured = /^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(config.url || '') &&
    typeof config.anonKey === 'string' && config.anonKey.length > 20 && !config.anonKey.includes('SUA_CHAVE');
  let client = null;
  let identity = null;
  let debounce;
  let access = new Map();
  const $ = (selector, root = document) => root.querySelector(selector);
  const escape = value => String(value || '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const errorText = error => error?.message || 'Não foi possível concluir a operação.';
  const notify = message => window.SEED_APP_TOAST ? window.SEED_APP_TOAST(message) : alert(message);

  function gateMarkup(message = '') {
    let root = $('#seed-auth-gate');
    if (!root) {
      root = document.createElement('div');
      root.id = 'seed-auth-gate';
      root.innerHTML = `<section class="seed-auth-card"><div class="seed-auth-brand">✦ <b>SEED</b></div><p class="seed-auth-kicker">GRIMÓRIO VIRTUAL</p><h1>Entre para sua mesa</h1><p class="seed-auth-copy">Acesse campanhas compartilhadas ou crie sua conta de Mestre ou jogador.</p><div class="seed-auth-tabs"><button type="button" data-auth-mode="login" class="active">Entrar</button><button type="button" data-auth-mode="signup">Criar conta</button></div><form id="seed-auth-form"><div class="seed-auth-name" hidden><label>Nome de exibição<input name="displayName" maxlength="80" autocomplete="name"></label><label>QUERO PARTICIPAR COMO<select name="appRole"><option value="player">Jogador</option><option value="master">Mestre</option></select></label></div><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Senha<input name="password" type="password" minlength="8" required autocomplete="current-password"></label><button class="seed-auth-submit" type="submit">Entrar</button><p class="seed-auth-error" aria-live="polite"></p></form><small>Use o endereço e a chave pública (anon) do seu projeto Supabase. Nunca coloque uma chave service_role no navegador.</small></section>`;
      document.body.append(root);
      root.addEventListener('click', event => {
        const tab = event.target.closest('[data-auth-mode]');
        if (!tab) return;
        root.dataset.mode = tab.dataset.authMode;
        root.querySelectorAll('[data-auth-mode]').forEach(button => button.classList.toggle('active', button === tab));
        $('.seed-auth-name', root).hidden = root.dataset.mode !== 'signup';
        $('input[name="password"]', root).autocomplete = root.dataset.mode === 'signup' ? 'new-password' : 'current-password';
        $('.seed-auth-submit', root).textContent = root.dataset.mode === 'signup' ? 'Criar conta' : 'Entrar';
        $('.seed-auth-error', root).textContent = '';
      });
      $('#seed-auth-form', root).addEventListener('submit', submitAuth);
    }
    $('.seed-auth-error', root).textContent = message;
    return root;
  }

  function removeGate() { $('#seed-auth-gate')?.remove(); }

  async function submitAuth(event) {
    event.preventDefault();
    const root = $('#seed-auth-gate'), form = event.currentTarget;
    const values = Object.fromEntries(new FormData(form));
    const button = $('.seed-auth-submit', form);
    const error = $('.seed-auth-error', form);
    button.disabled = true;
    error.textContent = '';
    try {
      if (root.dataset.mode === 'signup') {
        const { data, error: authError } = await client.auth.signUp({
          email: values.email, password: values.password,
          options: { data: { display_name: values.displayName, app_role: values.appRole } }
        });
        if (authError) throw authError;
        if (!data.session) {
          error.textContent = 'Conta criada. Confirme seu e-mail e depois entre.';
          button.disabled = false;
          return;
        }
        await client.rpc('seed_create_profile', { p_display_name: values.displayName, p_app_role: values.appRole });
      } else {
        const { error: authError } = await client.auth.signInWithPassword({ email: values.email, password: values.password });
        if (authError) throw authError;
      }
      await finishLogin();
    } catch (problem) {
      error.textContent = errorText(problem);
      button.disabled = false;
    }
  }

  async function finishLogin() {
    const { data: userData, error: userError } = await client.auth.getUser();
    if (userError || !userData.user) throw userError || new Error('Sessão não encontrada.');
    let { data: profile, error } = await client.from('seed_profiles').select('user_id,display_name,app_role').eq('user_id', userData.user.id).maybeSingle();
    if (error) throw error;
    if (!profile) {
      const metadata = userData.user.user_metadata || {};
      const { data, error: profileError } = await client.rpc('seed_create_profile', {
        p_display_name: metadata.display_name || userData.user.email,
        p_app_role: metadata.app_role === 'master' ? 'master' : 'player'
      });
      if (profileError) throw profileError;
      profile = data;
    }
    identity = { user: userData.user, profile };
    removeGate();
    document.body.classList.remove('seed-auth-required');
    updateProfile();
    window.dispatchEvent(new CustomEvent('seed:authenticated', { detail: identity }));
  }

  function updateProfile() {
    const card = $('.profile');
    if (!card || !identity) return;
    const name = identity.profile.display_name || identity.user.email || 'Aventureiro';
    const role = identity.profile.app_role === 'master' ? 'Mestre' : 'Jogador';
    card.innerHTML = `<div class="avatar avatar-gold">${escape(name.trim()[0]?.toUpperCase() || 'S')}</div><div><b>${escape(name)}</b><small>${role} · conta conectada</small></div><button id="seed-sign-out" title="Sair da conta">↪</button>`;
    $('#seed-sign-out').addEventListener('click', async () => {
      if (!confirm('Sair da sua conta SEED?')) return;
      await client.auth.signOut();
      identity = null;
      access.clear();
      location.reload();
    });
    const localCard = $('.local-card');
    if (localCard) localCard.innerHTML = '<span class="local-dot"></span><div><b>Conta conectada</b><small>Campanhas sincronizadas pelo Supabase</small></div>';
  }

  async function loadCampaigns() {
    if (!identity) return null;
    const [{ data: rows, error }, { data: memberships, error: memberError }] = await Promise.all([
      client.from('seed_campaigns').select('id,owner_id,payload,updated_at'),
      client.from('seed_campaign_members').select('campaign_id,user_id,member_role,status').eq('user_id', identity.user.id)
    ]);
    if (error) throw error;
    if (memberError) throw memberError;
    access = new Map();
    (rows || []).forEach(row => access.set(row.id, row.owner_id === identity.user.id ? 'owner' : 'member'));
    (memberships || []).forEach(member => access.set(member.campaign_id, member.status === 'active' ? 'member' : 'pending'));
    const campaigns = (rows || []).map(row => ({ ...row.payload, id: row.id, _seedOwnerId: row.owner_id, _seedAccess: access.get(row.id), _seedSystem: row.payload?._seedSystem || null }));
    const characters = campaigns.flatMap(campaign => campaign._seedCharacters || []);
    campaigns.forEach(campaign => { delete campaign._seedCharacters; });
    return { campaigns, characters, requests: (memberships || []).filter(member => member.status === 'pending'), access: Object.fromEntries(access) };
  }

  async function persistCampaigns(state) {
    if (!identity) return;
    for (const campaign of state.campaigns || []) {
      const permission = access.get(campaign.id);
      if (permission === 'pending') continue;
      const payload = { ...campaign, _seedCharacters: (state.characters || []).filter(character => character.campaignId === campaign.id), _seedSystem: (state.systems || []).find(system => system.id === campaign.systemId) || null };
      delete payload._seedOwnerId;
      delete payload._seedAccess;
      if (permission === 'owner') {
        const { error } = await client.from('seed_campaigns').update({ payload, updated_at: new Date().toISOString() }).eq('id', campaign.id);
        if (error) throw error;
      } else if (permission === 'member') {
        const { error } = await client.from('seed_campaigns').update({ payload, updated_at: new Date().toISOString() }).eq('id', campaign.id);
        if (error) throw error;
      } else if (identity.profile.app_role === 'master') {
        const { error } = await client.from('seed_campaigns').insert({ id: campaign.id, owner_id: identity.user.id, payload });
        if (error && error.code !== '23505') throw error;
        if (error?.code === '23505') throw new Error('Esta campanha já existe na nuvem, mas você não tem acesso para editá-la.');
        access.set(campaign.id, 'owner');
      }
    }
  }

  function scheduleSave(state) {
    if (!identity) return;
    clearTimeout(debounce);
    debounce = setTimeout(() => persistCampaigns(state).catch(problem => notify(`Falha ao sincronizar: ${errorText(problem)}`)), 500);
  }

  async function listMembers(campaignId) {
    const { data, error } = await client.from('seed_campaign_members').select('user_id,member_role,status,joined_at').eq('campaign_id', campaignId);
    if (error) throw error;
    return data || [];
  }

  async function listJoinRequests() {
    const ids = [...access].filter(([, role]) => role === 'owner').map(([id]) => id);
    if (!ids.length) return [];
    const { data, error } = await client.from('seed_campaign_members').select('campaign_id,user_id,member_role,status,joined_at').in('campaign_id', ids).eq('status', 'pending');
    if (error) throw error;
    return data || [];
  }

  async function initialize() {
    if (!configured) return { configured: false, identity: null };
    if (!window.supabase?.createClient) throw new Error('A biblioteca Supabase não carregou. Verifique a conexão e recarregue.');
    client = window.supabase.createClient(config.url, config.anonKey);
    document.body.classList.add('seed-auth-required');
    gateMarkup();
    const { data, error } = await client.auth.getSession();
    if (error) throw error;
    if (!data.session) return { configured: true, identity: null };
    try {
      await finishLogin();
      return { configured: true, identity };
    } catch (problem) {
      gateMarkup(`Falha ao carregar o perfil: ${errorText(problem)}`);
      await client.auth.signOut();
      return { configured: true, identity: null };
    }
  }

  window.SEED_CLOUD = {
    get configured() { return configured; },
    get identity() { return identity; },
    initialize,
    loadCampaigns,
    scheduleSave,
    createInvite: campaignId => client.rpc('seed_create_invite', { p_campaign_id: campaignId }),
    requestJoin: token => client.rpc('seed_request_join', { p_invite_token: token }),
    approveMember: (campaignId, userId) => client.rpc('seed_approve_member', { p_campaign_id: campaignId, p_user_id: userId }),
    removeMember: (campaignId, userId) => client.rpc('seed_remove_member', { p_campaign_id: campaignId, p_user_id: userId }),
    listMembers,
    listJoinRequests,
    async refresh() {
      const loaded = await loadCampaigns();
      if (loaded) window.dispatchEvent(new CustomEvent('seed:campaigns-loaded', { detail: loaded }));
      return loaded;
    }
  };
})();

-- SEED shared campaigns: run this once in Supabase SQL Editor.
-- Uses the Supabase Auth UID as the sole source of identity.
create extension if not exists pgcrypto with schema extensions;

create table if not exists public.seed_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '',
  app_role text not null check (app_role in ('master', 'player')),
  created_at timestamptz not null default now()
);

create table if not exists public.seed_campaigns (
  id text primary key,
  owner_id uuid not null references auth.users(id) on delete cascade,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.seed_campaign_members (
  campaign_id text not null references public.seed_campaigns(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  member_role text not null default 'player' check (member_role = 'player'),
  status text not null default 'pending' check (status in ('pending', 'active')),
  joined_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);

create table if not exists public.seed_campaign_invites (
  id uuid primary key default gen_random_uuid(),
  campaign_id text not null references public.seed_campaigns(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null default (now() + interval '7 days'),
  created_at timestamptz not null default now()
);

create index if not exists seed_campaign_members_user_idx
  on public.seed_campaign_members(user_id, status);
create index if not exists seed_campaign_invites_campaign_idx
  on public.seed_campaign_invites(campaign_id);

-- Security-definer predicates avoid recursive RLS checks between campaigns and memberships.
create or replace function public.seed_is_campaign_owner(p_campaign_id text)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.seed_campaigns c where c.id = p_campaign_id and c.owner_id = auth.uid()) $$;
create or replace function public.seed_is_active_member(p_campaign_id text)
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.seed_campaign_members m where m.campaign_id = p_campaign_id and m.user_id = auth.uid() and m.status = 'active') $$;
revoke all on function public.seed_is_campaign_owner(text) from public, anon;
revoke all on function public.seed_is_active_member(text) from public, anon;
grant execute on function public.seed_is_campaign_owner(text) to authenticated;
grant execute on function public.seed_is_active_member(text) to authenticated;

alter table public.seed_profiles enable row level security;
alter table public.seed_campaigns enable row level security;
alter table public.seed_campaign_members enable row level security;
alter table public.seed_campaign_invites enable row level security;

-- A profile can only be read/created by its owner. Role changes are intentionally
-- excluded from UPDATE so changing roles requires a new account / trusted admin.
drop policy if exists seed_profiles_read_self on public.seed_profiles;
create policy seed_profiles_read_self on public.seed_profiles
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists seed_profiles_insert_self on public.seed_profiles;
create policy seed_profiles_insert_self on public.seed_profiles
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists seed_profiles_update_name on public.seed_profiles;
create policy seed_profiles_update_name on public.seed_profiles
  for update to authenticated using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
revoke update on public.seed_profiles from authenticated;
grant update (display_name) on public.seed_profiles to authenticated;

-- Campaign payload is visible to the owner and approved members. Approved players
-- may update shared play state; only the owner may create or delete a campaign.
drop policy if exists seed_campaigns_read_members on public.seed_campaigns;
create policy seed_campaigns_read_members on public.seed_campaigns
  for select to authenticated using (
    owner_id = (select auth.uid()) or public.seed_is_active_member(id)
  );
drop policy if exists seed_campaigns_insert_owner on public.seed_campaigns;
create policy seed_campaigns_insert_owner on public.seed_campaigns
  for insert to authenticated with check (
    owner_id = (select auth.uid()) and exists (
      select 1 from public.seed_profiles p
      where p.user_id = (select auth.uid()) and p.app_role = 'master'
    )
  );
drop policy if exists seed_campaigns_update_members on public.seed_campaigns;
create policy seed_campaigns_update_members on public.seed_campaigns
  for update to authenticated using (
    owner_id = (select auth.uid()) or public.seed_is_active_member(id)
  ) with check (
    owner_id = (select auth.uid()) or public.seed_is_active_member(id)
  );
drop policy if exists seed_campaigns_delete_owner on public.seed_campaigns;
create policy seed_campaigns_delete_owner on public.seed_campaigns
  for delete to authenticated using (owner_id = (select auth.uid()));

-- Memberships are private: a participant sees their own status; the campaign
-- owner sees all requests. Mutations are only available through the RPCs below.
drop policy if exists seed_members_read_related on public.seed_campaign_members;
create policy seed_members_read_related on public.seed_campaign_members
  for select to authenticated using (
    user_id = (select auth.uid()) or public.seed_is_campaign_owner(campaign_id)
  );
revoke insert, update, delete on public.seed_campaign_members from authenticated;

-- Invite hashes are never readable through the client API.
revoke all on public.seed_campaign_invites from anon, authenticated;

create or replace function public.seed_create_profile(p_display_name text, p_app_role text)
returns public.seed_profiles
language plpgsql security definer set search_path = ''
as $$
declare result public.seed_profiles;
begin
  if auth.uid() is null or p_app_role not in ('master', 'player') then
    raise exception 'Perfil inválido';
  end if;
  insert into public.seed_profiles(user_id, display_name, app_role)
  values (auth.uid(), left(trim(coalesce(p_display_name, '')), 80), p_app_role)
  on conflict (user_id) do nothing;
  select * into result from public.seed_profiles where user_id = auth.uid();
  return result;
end;
$$;

create or replace function public.seed_create_invite(p_campaign_id text)
returns text
language plpgsql security definer set search_path = ''
as $$
declare token text;
begin
  if not exists (select 1 from public.seed_campaigns c
    where c.id = p_campaign_id and c.owner_id = auth.uid()) then
    raise exception 'Somente o Mestre da campanha pode convidar';
  end if;
  token := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.seed_campaign_invites(campaign_id, token_hash)
  values (p_campaign_id, encode(extensions.digest(token, 'sha256'), 'hex'));
  return token;
end;
$$;

create or replace function public.seed_request_join(p_invite_token text)
returns text
language plpgsql security definer set search_path = ''
as $$
declare target_campaign text;
begin
  if auth.uid() is null or coalesce(length(p_invite_token), 0) < 32 then
    raise exception 'Convite inválido ou expirado';
  end if;
  select i.campaign_id into target_campaign
  from public.seed_campaign_invites i
  where i.token_hash = encode(extensions.digest(p_invite_token, 'sha256'), 'hex')
    and i.expires_at > now();
  if target_campaign is null then raise exception 'Convite inválido ou expirado'; end if;
  insert into public.seed_campaign_members(campaign_id, user_id, member_role, status)
  values (target_campaign, auth.uid(), 'player', 'pending')
  on conflict (campaign_id, user_id) do nothing;
  return target_campaign;
end;
$$;

create or replace function public.seed_approve_member(p_campaign_id text, p_user_id uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (select 1 from public.seed_campaigns c
    where c.id = p_campaign_id and c.owner_id = auth.uid()) then
    raise exception 'Somente o Mestre da campanha pode aprovar participantes';
  end if;
  update public.seed_campaign_members set status = 'active'
  where campaign_id = p_campaign_id and user_id = p_user_id and status = 'pending';
  if not found then raise exception 'Solicitação não encontrada'; end if;
end;
$$;

create or replace function public.seed_remove_member(p_campaign_id text, p_user_id uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (select 1 from public.seed_campaigns c
    where c.id = p_campaign_id and c.owner_id = auth.uid()) then
    raise exception 'Somente o Mestre da campanha pode remover participantes';
  end if;
  delete from public.seed_campaign_members
  where campaign_id = p_campaign_id and user_id = p_user_id;
end;
$$;

revoke all on function public.seed_create_profile(text, text) from public, anon;
revoke all on function public.seed_create_invite(text) from public, anon;
revoke all on function public.seed_request_join(text) from public, anon;
revoke all on function public.seed_approve_member(text, uuid) from public, anon;
revoke all on function public.seed_remove_member(text, uuid) from public, anon;
grant execute on function public.seed_create_profile(text, text) to authenticated;
grant execute on function public.seed_create_invite(text) to authenticated;
grant execute on function public.seed_request_join(text) to authenticated;
grant execute on function public.seed_approve_member(text, uuid) to authenticated;
grant execute on function public.seed_remove_member(text, uuid) to authenticated;

grant select, insert, delete on public.seed_campaigns to authenticated;
revoke update on public.seed_campaigns from authenticated;
grant update (payload, updated_at) on public.seed_campaigns to authenticated;
grant select on public.seed_campaign_members to authenticated;
grant select on public.seed_profiles to authenticated;

view-root');root.innerHTML=`${pageHead('Personagens','Heróis, antagonistas e destinos entrelaçados.','<button class="primary-btn" data-action="create-character">＋ Novo personagem</button>')}<div class="toolbar-row"><div class="search-box"><input id="character-search" placeholder="Buscar personagem..." /></div><select class="select-control" id="character-system-filter"><option value="all">Todos os sistemas</option>${state.systems.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="character-grid" id="character-list">${state.characters.length?state.characters.map(characterCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><b>Uma lenda começa com um nome</b>Crie sua primeira ficha dinâmica e leve-a para qualquer mesa.<br><button class="primary-btn" data-action="create-character">＋ Criar personagem</button></div>'}</div>`;}
