  function createSession(campaign){openModal('Agendar sessão',`<form id="session-form"><div class="form-grid">${field('NOME DA SESSÃO','name','Sessão de jogo')}${field('DATA','date','','date')}${field('HORÁRIO','time','','time')}<div class="field full"><label>NOTAS / PREPARAÇÃO</label><textarea name="notes" placeholder="Pauta, recados ou preparação"></textarea></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-session="${campaign.id}">Agendar</button>`);}
  function createToken(){const c=currentCampaign();if(!c){toast('Crie uma campanha antes de abrir a mesa.');navigate('campaigns');return;}openModal('Adicionar token',`<form id="token-form"><div class="form-grid">${field('NOME','name','Novo aventureiro')}<div class="field"><label>PERSONAGEM VINCULADO</label><select name="characterId"><option value="">Token livre</option>${state.characters.map(ch=>`<option value="${ch.id}">${escapeHtml(ch.name)}</option>`).join('')}</select></div><div class="field"><label>TIPO</label><select name="kind"><option value="hero">Aliado</option><option value="enemy">Adversário</option><option value="neutral">Neutro</option></select></div><div class="field"><label>INICIATIVA</label><input name="initiative" type="number" value="10"></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-token>Adicionar token</button>`);}
  function parseRoll(expression){const m=String(expression).trim().toLowerCase().match(/^(\d*)d(\d+)(?:\s*([+-])\s*(\d+))?$/);if(!m)throw new Error('Use uma fórmula como d20, 2d6+3 ou 1d100.');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[4]||0)*(m[3]==='-'?-1:1);if(count<1||count>100||sides<2||sides>10000||mod>100000||mod< -100000)throw new Error('Limites: até 100 dados, d2–d10000 e modificador de 100000.');const dice=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return{expression:String(expression).trim(),dice,mod,total:dice.reduce((a,b)=>a+b,0)+mod};}
  function recordRoll(expression,author='Mestre'){try{const r=parseRoll(expression);r.id=uid();r.time=Date.now();r.author=author;state.rolls.unshift(r);state.rolls=state.rolls.slice(0,100);const c=currentCampaign();if(c){c.chat=c.chat||[];c.chat.push({id:uid(),author,text:`rolou ${r.expression}: ${r.total}`,roll:true,time:r.time});c.chat=c.chat.slice(-100);}save();if(currentView==='tabletop')renderTabletop();else renderDashboard();return r;}catch(e){toast(e.message);return null;}}
  function diceModal(){const recent=state.rolls.slice(0,8);openModal('Rolar dados',`<form id="roll-form"><div class="field"><label>FÓRMULA</label><input name="formula" value="d20" placeholder="d20, 2d6+3" required></div></form><div class="roll-history">${recent.map(r=>`<div class="roll-item"><span>${escapeHtml(r.expression)} · ${new Date(r.time).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span><b>${r.total}</b></div>`).join('')||'<p class="muted">Suas rolagens aparecerão aqui.</p>'}</div>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-roll-modal>Rolar</button>`);}
  function renderTabletop(){const root=$('#view-root'),c=currentCampaign();if(!c){root.innerHTML=`<div class="empty-state"><b>A mesa precisa de uma campanha</b>Crie ou selecione uma campanha para abrir o mapa, tokens e combate.<br><button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button></div>`;return;}const t=tabletopFor(c),asset=state.assets.find(a=>a.id===t.mapAssetId);root.innerHTML=`<section class="tabletop-view"><div class="session-bar"><div class="session-title">${escapeHtml(c.name)} <small>· ${escapeHtml(getSystem(c.systemId).name)}</small></div><div class="session-tools"><button data-action="new-session" class="hide-mobile">◷ Sessão</button><button data-action="map-image" class="hide-mobile">▧ Mapa</button><button data-action="toggle-grid">Grade: ${t.gridType==='none'?'off':t.grid+'px'}</button><button data-action="add-token">＋ Token</button></div></div><div class="tabletop-layout"><div class="map-tools"><button class="map-tool ${activeTool==='select'?'active':''}" data-tool="select" title="Selecionar / mover">↖</button><button class="map-tool ${activeTool==='pan'?'active':''}" data-tool="pan" title="Mover mapa">✥</button><button class="map-tool ${activeTool==='token'?'active':''}" data-tool="token" title="Adicionar token">♙</button><button class="map-tool ${activeTool==='measure'?'active':''}" data-tool="measure" title="Medir distância">↔</button><button class="map-tool ${activeTool==='fog'?'active':''}" data-tool="fog" title="Ocultar área (pinte no mapa)">▧</button><button class="map-tool ${activeTool==='reveal'?'active':''}" data-tool="reveal" title="Revelar área">☼</button><div class="tool-divider"></div><button class="map-tool" data-action="map-image" title="Escolher mapa">▧</button><button class="map-tool" data-action="toggle-grid" title="Alternar grade">▦</button><button class="map-tool" data-action="center-map" title="Centralizar">⌖</button></div><div class="map-workspace"><canvas id="map-canvas" class="map-canvas" aria-label="Mapa da mesa"></canvas><div class="map-hud"><span class="hud-chip">${asset?escapeHtml(asset.name):'MAPA SEM IMAGEM'}</span><span class="hud-chip">${t.gridType==='none'?'SEM GRADE':t.gridType==='hex'?'GRADE HEXAGONAL':`GRADE ${t.grid}px`}</span></div><div class="map-zoom"><button data-zoom="out">−</button><button data-zoom="in">＋</button><button data-action="center-map">⌖</button></div></div><aside class="map-right"><div class="right-tabs"><button class="active" data-tab="combat">Combate</button><button data-tab="tokens">Tokens</button><button data-tab="notes">Notas</button></div><div class="right-content" id="tabletop-panel"></div></aside></div><div class="bottom-dock"><section class="chat-panel"><div class="dock-heading">CHAT DA MESA <small>Somente neste dispositivo</small></div><div class="chat-log" id="chat-log">${(c.chat||[]).slice(-20).map(m=>`<p class="chat-line"><b>${escapeHtml(m.author||'Mestre')}</b><span class="${m.roll?'roll-text':''}">${escapeHtml(m.text)}</span></p>`).join('')||'<p class="chat-line">A conversa da mesa começa aqui.</p>'}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Mensagem ou /roll 2d6+2" autocomplete="off"><button>Enviar</button></form></section><section class="dice-panel"><div class="dock-heading">✦ &nbsp; ROLAGEM RÁPIDA</div><div class="quick-rolls">${[4,6,8,10,12,20].map(n=>`<button data-quick-roll="d${n}">d${n}</button>`).join('')}</div><form class="inline-roll" id="inline-roll"><input name="formula" value="d20" aria-label="Fórmula de dados"><button>Rolar</button></form><div class="dice-last">${state.rolls[0]?`${escapeHtml(state.rolls[0].expression)} = ${state.rolls[0].total}`:'Nenhuma rolagem ainda'}</div></section></div></section>`;renderTabletopPanel();initCanvas();}
  let tabletopTab='combat',activeTool='select',canvasObserver;
  function renderTabletopPanel(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c),panel=$('#tabletop-panel');if(!panel)return;if(tabletopTab==='combat'){const order=t.initiative||[],cur=order[t.turnIndex||0];panel.innerHTML=`<div class="panel-heading">Iniciativa <button data-action="start-combat" title="Iniciar combate">⚄</button></div>${cur?`<div class="turn-card"><small>RODADA ${t.round||1} · TURNO ATUAL</small><b>${escapeHtml(cur.name)}</b><div class="turn-actions"><button class="secondary-btn" data-action="next-turn">Próximo turno →</button><button class="secondary-btn" data-action="end-combat">Encerrar</button></div></div>`:''}<div class="combat-controls"><button class="secondary-btn" data-action="start-combat">⚄ Iniciar / rolar iniciativa</button><button class="secondary-btn" data-action="add-token">＋</button></div>${order.length?`<div class="initiative-list-mobile">${order.map((x,i)=>`<div class="initiative-row ${i===(t.turnIndex||0)?'turn-current':''}"><span class="initiative-number">${x.score}</span><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':'Aliado'}</small></span><button class="text-button" data-remove-initiative="${x.id}">×</button></div>`).join('')}</div>`:'<div class="combat-empty">Adicione tokens e role a iniciativa para acompanhar o combate.</div>'}`;}else if(tabletopTab==='tokens'){panel.innerHTML=`<div class="panel-heading">Tokens no mapa <button data-action="add-token">＋</button></div>${t.tokens.length?t.tokens.map(x=>`<div class="initiative-row"><span class="initiative-avatar">${escapeHtml((x.name||'?')[0])}</span><span class="initiative-info"><b>${escapeHtml(x.name)}</b><small>${x.kind==='enemy'?'Adversário':x.kind==='hero'?'Aliado':'Neutro'}</small></span><button class="text-button" data-remove-token="${x.id}">×</button></div>`).join(''):'<div class="combat-empty">Nenhum token. Use ＋ para adicionar.</div>'}<div class="token-actions"><button data-action="add-character-token">Adicionar personagem</button></div>`;}else{panel.innerHTML=`<div class="panel-heading">Notas da campanha</div><textarea id="table-notes" placeholder="Anotações visíveis apenas para este dispositivo..." style="width:100%;min-height:120px">${escapeHtml(c.tabletop.notes||'')}</textarea><button class="secondary-btn" data-action="save-notes" style="margin-top:8px">Salvar notas</button>`;}}
  function initCanvas(){const canvas=$('#map-canvas');if(!canvas)return;const c=currentCampaign(),t=tabletopFor(c),ctx=canvas.getContext('2d');let bgImage=null,measureStart=null,measureEnd=null,measurePointer=null;const asset=state.assets.find(a=>a.id===t.mapAssetId);if(asset?.type?.startsWith('image/')){bgImage=new Image();bgImage.onload=draw;bgImage.src=asset.data;}let w=0,h=0;function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);w=rect.width;h=rect.height;canvas.width=Math.max(1,w*dpr);canvas.height=Math.max(1,h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}function draw(){if(!w||!h)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#25231d';ctx.fillRect(0,0,w,h);if(bgImage?.complete&&bgImage.naturalWidth){const scale=Math.max(w/bgImage.naturalWidth,h/bgImage.naturalHeight)*t.zoom;const iw=bgImage.naturalWidth*scale,ih=bgImage.naturalHeight*scale;ctx.drawImage(bgImage,(w-iw)/2+t.panX,(h-ih)/2+t.panY,iw,ih);}else{ctx.fillStyle='#302c22';for(let i=0;i<30;i++){const x=((i*137)%Math.max(w,1)),y=((i*83)%Math.max(h,1));ctx.globalAlpha=.12;ctx.beginPath();ctx.arc(x,y,(i%4)+1,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
      if(t.gridType!=='none'){const g=Number(t.grid)||64;ctx.strokeStyle='#d8c99a35';ctx.lineWidth=1;ctx.beginPath();if(t.gridType==='hex'){const dx=g,dy=g*.866;for(let row=-2;row<h/dy+3;row++)for(let col=-2;col<w/dx+3;col++){const x=col*dx+(row%2)*dx/2+t.panX%dx,y=row*dy+t.panY%dy;for(let k=0;k<6;k++){const a=Math.PI/3*k;const px=x+Math.cos(a)*g/2,py=y+Math.sin(a)*g/2;k?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();}}else{const ox=((t.panX%g)+g)%g,oy=((t.panY%g)+g)%g;for(let x=ox;x<w;x+=g){ctx.moveTo(x,0);ctx.lineTo(x,h);}for(let y=oy;y<h;y+=g){ctx.moveTo(0,y);ctx.lineTo(w,y);}}ctx.stroke();}
      (t.tokens||[]).forEach(tok=>{const x=tok.x,y=tok.y,r=22;ctx.save();ctx.shadowColor=tok.kind==='enemy'?'#a64d46':'#d0ac57';ctx.shadowBlur=12;ctx.fillStyle=tok.kind==='enemy'?'#63352f':tok.kind==='neutral'?'#3c4a49':'#65532f';ctx.strokeStyle=tok.kind==='enemy'?'#c16f60':'#d3b86e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#f0e5c9';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText((tok.name||'?').slice(0,1).toUpperCase(),x,y);ctx.fillStyle='#eee2c9';ctx.font='10px sans-serif';ctx.fillText(tok.name,x,y+r+13);ctx.restore();});const fogSize=t.gridType==='none'?48:Number(t.grid)||64;ctx.fillStyle='rgba(9,10,9,.94)';(t.fogCells||[]).forEach(key=>{const [col,row]=key.split(',').map(Number);ctx.fillRect(col*fogSize+t.panX,row*fogSize+t.panY,fogSize,fogSize);});if(measureStart){ctx.save();ctx.strokeStyle='#e6c875';ctx.lineWidth=2;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(measureStart.x,measureStart.y);if(measureEnd)ctx.lineTo(measureEnd.x,measureEnd.y);else if(measurePointer)ctx.lineTo(measurePointer.x,measurePointer.y);ctx.stroke();ctx.setLineDash([]);const end=measureEnd||measurePointer;if(end){const dist=Math.hypot(end.x-measureStart.x,end.y-measureStart.y),units=t.gridType==='none'?Math.round(dist/48*5):Math.round(dist/(Number(t.grid)||64)*5);const label=`${units} pés`;const mx=(measureStart.x+end.x)/2,my=(measureStart.y+end.y)/2;ctx.font='12px sans-serif';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#171612';ctx.fillRect(mx-31,my-20,62,18);ctx.fillStyle='#f0dfa9';ctx.fillText(label,mx,my-5);}ctx.restore();}}
    resize();if(canvasObserver)canvasObserver.disconnect();canvasObserver=new ResizeObserver(resize);canvasObserver.observe(canvas.parentElement);let drag=null;const pos=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};};const paintFog=(p,hide,from)=>{const size=t.gridType==='none'?48:Number(t.grid)||64,steps=from?Math.max(1,Math.ceil(Math.hypot(p.x-from.x,p.y-from.y)/(size/3))):1;for(let i=1;i<=steps;i++){const x=from?from.x+(p.x-from.x)*i/steps:p.x,y=from?from.y+(p.y-from.y)*i/steps:p.y,col=Math.floor((x-t.panX)/size),row=Math.floor((y-t.panY)/size),key=`${col},${row}`;if(hide&&!t.fogCells.includes(key))t.fogCells.push(key);if(!hide)t.fogCells=t.fogCells.filter(cell=>cell!==key);}};canvas.onpointerdown=e=>{const p=pos(e),hit=[...t.tokens].reverse().find(tok=>Math.hypot(tok.x-p.x,tok.y-p.y)<25);if(activeTool==='token'){addTokenAt(p.x,p.y);return;}if(activeTool==='fog'||activeTool==='reveal'){drag={kind:activeTool,p};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');paintFog(p,activeTool==='fog');draw();return;}if(activeTool==='measure'){if(!measureStart||measureEnd){measureStart=p;measureEnd=null;}else measureEnd=p;measurePointer=p;canvas.setPointerCapture(e.pointerId);draw();return;}if(activeTool==='select'&&hit){drag={kind:'token',token:hit,p};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');}else if(activeTool==='pan'){drag={kind:'pan',p,px:t.panX,py:t.panY};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');}};canvas.onpointermove=e=>{const p=pos(e);if(activeTool==='measure'&&measureStart&&!measureEnd){measurePointer=p;draw();}if(!drag)return;if(drag.kind==='token'){drag.token.x=p.x;drag.token.y=p.y;}else if(drag.kind==='pan'){t.panX=drag.px+p.x-drag.p.x;t.panY=drag.py+p.y-drag.p.y;}else if(drag.kind==='fog'||drag.kind==='reveal'){paintFog(p,drag.kind==='fog',drag.p);drag.p=p;}draw();};canvas.onpointerup=()=>{if(drag?.kind==='token'){const g=t.grid||64;if(t.gridType!=='none'){drag.token.x=Math.round(drag.token.x/g)*g+g/2;drag.token.y=Math.round(drag.token.y/g)*g+g/2;}save();renderTabletopPanel();}else if(drag)save();else if(activeTool==='fog'||activeTool==='reveal')save();drag=null;canvas.classList.remove('dragging');};canvas.onpointercancel=canvas.onpointerup;canvas.onwheel=e=>{e.preventDefault();t.zoom=Math.max(.4,Math.min(2.5,t.zoom*(e.deltaY<0?1.1:.9)));save();draw();};function addTokenAt(x,y){const token={id:uid(),name:'Novo token',kind:'hero',x,y};t.tokens.push(token);save();draw();renderTabletopPanel();openTokenEditor(token);}}
  function openTokenEditor(token){openModal('Nomear token',`<form id="token-name-form">${field('NOME','name',token.name)}<div class="field"><label>TIPO</label><select name="kind"><option value="hero" ${token.kind==='hero'?'selected':''}>Aliado</option><option value="enemy" ${token.kind==='enemy'?'selected':''}>Adversário</option><option value="neutral" ${token.kind==='neutral'?'selected':''}>Neutro</option></select></div></form>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-save-token-name="${token.id}">Salvar</button>`);}

  function showMapPicker(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c);openModal('Escolher mapa',`<div class="field"><label>IMAGEM DA BIBLIOTECA</label><select id="map-asset-select"><option value="">Mapa sem imagem</option>${state.assets.filter(a=>a.type?.startsWith('image/')).map(a=>`<option value="${a.id}" ${a.id===t.mapAssetId?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></div><p class="muted">Importe imagens pela Biblioteca para usá-las como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-map>Aplicar mapa</button>`);}
  function chooseUpload(category='Outros'){const input=document.createElement('input');input.type='file';input.accept='image/*,.pdf,.txt';input.multiple=true;input.onchange=async()=>{for(const file of [...input.files]){if(file.size>1500000){toast(`${file.name}: limite local de 1,5 MB por arquivo.`);continue;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});state.assets.push({id:uid(),name:file.name,type:file.type||'application/octet-stream',size:file.size,category,data});}catch{toast(`Não foi possível ler ${file.name}.`);}}save();render();if(state.assets.length)logActivity('Novos arquivos foram adicionados à biblioteca.');};input.click();}
  function safeImport(data){if(!data||typeof data!=='object'||!Array.isArray(data.campaigns)||!Array.isArray(data.characters)||!Array.isArray(data.systems))throw new Error('Arquivo de backup inválido.');const base=defaults();state={...base,...data,assets:Array.isArray(data.assets)?data.assets:[],rolls:Array.isArray(data.rolls)?data.rolls:[],activity:Array.isArray(data.activity)?data.activity:[],settings:{...base.settings,...(data.settings||{})}};state.campaigns.forEach(c=>{c.sessions=c.sessions||[];c.tabletop=c.tabletop||{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0};c.chat=c.chat||[];});save();render();toast('Cópia restaurada com sucesso.');}
