  function sessionSummary(){const sessions=state.campaigns.flatMap(c=>(c.sessions||[]).filter(s=>s.status==='Agendada').map(s=>({c,s}))).slice(0,4);return sessions.length?sessions.map(({c,s})=>`<div class="session-item"><div class="session-date"><b>${s.date?new Date(s.date+'T12:00:00').getDate():'—'}</b><small>${s.date?new Date(s.date+'T12:00:00').toLocaleString('pt-BR',{month:'short'}).toUpperCase():'DATA'}</small></div><div class="session-desc"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(c.name)} · ${s.time||'Horário livre'}</small></div></div>`).join(''):'<div class="session-item"><div class="session-desc"><b>O destino está em aberto</b><small>Agende uma sessão dentro de uma campanha.</small></div></div>';}
  function renderCampaigns(){const root=$('#view-root'),cloud=window.SEED_CLOUD,identity=cloud?.identity,canCreate=!cloud?.configured||identity?.profile?.app_role==='master';root.innerHTML=`${pageHead('Campanhas','Seus mundos, histórias e grupos em um único lugar.',canCreate?'<button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button>':'')}<div class="toolbar-row"><div class="search-box"><input id="campaign-search" placeholder="Buscar campanha..." /></div><select class="select-control" id="campaign-filter"><option value="all">Todas as campanhas</option><option value="active">Em andamento</option><option value="archived">Arquivadas</option></select></div>${identity?`<form id="cloud-join-form" class="cloud-join-form"><label for="cloud-invite-token">Entrar em uma campanha</label><input id="cloud-invite-token" name="inviteToken" placeholder="Cole aqui o código de convite" required><button class="secondary-btn" type="submit">Solicitar participação</button><small>O Mestre precisará aprovar sua solicitação.</small></form>${state.cloudRequests?.length?`<div class="cloud-pending-list"><b>Solicitações aguardando aprovação</b>${state.cloudRequests.map(request=>`<span>Campanha ${escapeHtml(request.campaign_id)}</span>`).join('')}</div>`:''}<div class="list-grid" id="campaign-list">${state.campaigns.length?state.campaigns.map(c=>{const owner=c._seedAccess==='owner',cloudMember=c._seedAccess==='member',pending=c._seedAccess==='pending';return `<article class="campaign-tile" ${pending?'':'data-open-campaign="'+escapeHtml(c.id)+'"'}>${art(c.rune||'✧',c.status||'EM ANDAMENTO')}<div class="tile-body"><h3>${escapeHtml(c.name)}${pending?' · solicitação pendente':''}</h3><p>${escapeHtml(c.description||'Sem descrição. Abra para configurar a campanha.')}</p><div class="campaign-meta"><span>${escapeHtml(getSystem(c.systemId).name)}</span><span>${(c.sessions||[]).length} sessões</span></div><div class="tile-actions">${!pending?`<button class="secondary-btn" data-enter="${c.id}">Abrir mesa</button>`:''}${(!cloud?.configured||owner)?`<button class="secondary-btn" data-edit-campaign="${c.id}">Editar</button>`:''}${!pending?`<button class="secondary-btn" data-session="${c.id}">＋ Sessão</button>`:''}${owner?`<button class="secondary-btn" data-members="${c.id}">Participantes</button>`:''}${cloudMember?'<span class="tag">JOGADOR</span>':''}</div></div></article>`;}).join(''):`<div class="empty-state" style="grid-column:1/-1"><b>Nenhuma campanha encontrada</b>${canCreate?'Inicie uma campanha para preparar sua mesa.':'Use um convite para solicitar acesso a uma campanha.'}<br>${canCreate?'<button class="primary-btn" data-action="create-campaign">＋ Criar campanha</button>':''}</div>`}</div>`;}
  function renderCharacters(){const root=$('#view-root');root.innerHTML=`${pageHead('Personagens','Heróis, antagonistas e destinos entrelaçados.','<button class="primary-btn" data-action="create-character">＋ Novo personagem</button>')}<div class="toolbar-row"><div class="search-box"><input id="character-search" placeholder="Buscar personagem..." /></div><select class="select-control" id="character-system-filter"><option value="all">Todos os sistemas</option>${state.systems.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="character-grid" id="character-list">${state.characters.length?state.characters.map(characterCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><b>Uma lenda começa com um nome</b>Crie sua primeira ficha dinâmica e leve-a para qualquer mesa.<br><button class="primary-btn" data-action="create-character">＋ Criar personagem</button></div>'}</div>`;}
  function characterCard(ch){const sys=getSystem(ch.systemId);const hp=Number(ch.hp)||0,max=Number(ch.maxHp)||1;return `<article class="character-card" data-character="${ch.id}"><div class="character-top"><div class="portrait">${ch.image?`<img src="${ch.image}" alt=""/>`:escapeHtml((ch.name||'?')[0].toUpperCase())}</div><div><h3>${escapeHtml(ch.name)}</h3><p class="muted">${escapeHtml(ch.role||'Aventureiro')} · ${escapeHtml(sys.name)}</p></div></div><div class="character-stats"><div class="mini-stat"><small>NÍVEL</small>${escapeHtml(ch.level||'—')}</div><div class="mini-stat"><small>PV</small>${hp} / ${max}<div class="resource-bar"><i style="width:${Math.max(0,Math.min(100,hp/max*100))}%"></i></div></div>${Object.entries(ch.attributes||{}).slice(0,1).map(([k,v])=>`<div class="mini-stat"><small>${escapeHtml(k.toUpperCase())}</small>${escapeHtml(v)}</div>`).join('')}</div><div class="character-footer"><span class="tag">${escapeHtml(ch.campaignName||'SEM CAMPANHA')}</span><button class="text-button" data-edit-character="${ch.id}">Editar ficha →</button></div></article>`;}
  function handleAction(action){const c=currentCampaign(),t=c&&tabletopFor(c);switch(action){case'create-campaign':createCampaign();break;case'create-character':createCharacter();break;case'create-system':createSystem();break;case'new-session':if(c)createSession(c);else toast('Crie uma campanha primeiro.');break;case'add-token':createToken();break;case'add-character-token':if(!c)return;{const ch=state.characters[0];if(!ch){toast('Crie um personagem antes de vinculá-lo.');return;}const token={id:uid(),name:ch.name,kind:'hero',x:160+(t.tokens.length%4)*64,y:140+Math.floor(t.tokens.length/4)*64,characterId:ch.id};t.tokens.push(token);save();renderTabletop();}break;case'toggle-grid':if(t){t.gridType=t.gridType==='none'?'square':t.gridType==='square'?'hex':'none';save();renderTabletop();}break;case'map-image':showMapPicker();break;case'center-map':if(t){t.panX=0;t.panY=0;t.zoom=1;save();renderTabletop();}break;case'save-notes':if(c){t.notes=$('#table-notes')?.value||'';save();toast('Notas salvas neste dispositivo.');}break;case'start-combat':if(!t||!t.tokens.length){toast('Adicione ao menos um token antes de iniciar o combate.');return;}t.initiative=t.tokens.map(x=>({...x,score:Number(x.initiative)||1+Math.floor(Math.random()*20)})).sort((a,b)=>b.score-a.score);t.turnIndex=0;t.round=1;save();renderTabletopPanel();break;case'next-turn':if(t?.initiative.length){t.turnIndex=(t.turnIndex+1)%t.initiative.length;if(t.turnIndex===0)t.round=(t.round||1)+1;save();renderTabletopPanel();}break;case'end-combat':if(t){t.initiative=[];t.turnIndex=0;t.round=1;save();renderTabletopPanel();}break;case'upload-asset':openModal('Importar para biblioteca',`<div class="field"><label>CATEGORIA</label><select id="upload-category"><option>Mapas</option><option>Tokens</option><option>Retratos</option><option selected>Outros</option></select></div><p class="muted">Arquivos de até 1,5 MB são guardados localmente. Imagens podem ser usadas como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-start-upload>Escolher arquivo</button>`);break;case'export-data':download('seed-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));break;case'import-data':{const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{safeImport(JSON.parse(reader.result));}catch(e){toast(e.message||'Não foi possível restaurar o arquivo.');}};reader.readAsText(file);};input.click();}break;case'clear-data':if(confirm('Apagar todas as campanhas, personagens, rolagens e arquivos locais? Esta ação não pode ser desfeita.')){state=defaults();save();navigate('dashboard');toast('Dados locais apagados.');}break;}}

  async function openMemberManager(campaignId){const campaign=campaignById(campaignId);if(!campaign)return;try{const members=await window.SEED_CLOUD.listMembers(campaignId);const rows=members.length?members.map(member=>`<div class="cloud-member-row"><div><b>${member.status==='pending'?'Solicitação pendente':'Participante'}</b><small>${escapeHtml(member.user_id)}</small></div><div class="cloud-member-actions">${member.status==='pending'?`<button class="secondary-btn" data-approve-member="${escapeHtml(member.user_id)}" data-campaign-id="${escapeHtml(campaignId)}">Aprovar</button>`:''}<button class="danger-btn" data-remove-member="${escapeHtml(member.user_id)}" data-campaign-id="${escapeHtml(campaignId)}">${member.status==='pending'?'Recusar':'Remover'}</button></div></div>`).join(''):'<p class="muted">Ainda não há solicitações nem participantes.</p>';openModal(`Participantes · ${escapeHtml(campaign.name)}`,`<div class="cloud-members-list">${rows}</div><div class="cloud-invite-box"><p>Crie um código temporário para convidar um jogador. O código é mostrado uma única vez.</p><button class="secondary-btn" data-create-invite="${escapeHtml(campaignId)}">＋ Gerar convite</button><div id="cloud-invite-result"></div></div>`,'<button class="secondary-btn" data-close-modal>Fechar</button>',true);}catch(error){toast(`Não foi possível carregar participantes: ${error.message||error}`);}}
