22:   user_id uuid not null references auth.users(id) on delete cascade,
23:   member_role text not null default 'player' check (member_role = 'player'),
24:   status text not null default 'pending' check (status in ('pending', 'active')),
25:   joined_at timestamptz not null default now(),
26:   primary key (campaign_id, user_id)
