112: create or replace function public.seed_create_profile(p_display_name text, p_app_role text)
113: returns public.seed_profiles
114: language plpgsql security definer set search_path = ''
115: as $$
116: declare result public.seed_profiles;
117: begin
118:   if auth.uid() is null or p_app_role not in ('master', 'player') then
119:     raise exception 'Perfil inválido';
120:   end if;
121:   insert into public.seed_profiles(user_id, display_name, app_role)
122:   values (auth.uid(), left(trim(coalesce(p_display_name, '')), 80), p_app_role)
