129: create or replace function public.seed_create_invite(p_campaign_id text)
130: returns text
131: language plpgsql security definer set search_path = ''
132: as $$
133: declare token text;
134: begin
135:   if not exists (select 1 from public.seed_campaigns c
136:     where c.id = p_campaign_id and c.owner_id = auth.uid()) then
137:     raise exception 'Somente o Mestre da campanha pode convidar';
138:   end if;
139:   token := encode(extensions.gen_random_bytes(24), 'hex');
140:   insert into public.seed_campaign_invites(campaign_id, token_hash)
141:   values (p_campaign_id, encode(extensions.digest(token, 'sha256'), 'hex'));
142:   return token;
143: end;
144: $$;
